window.PTV_TOOLS_DATA = {"saoHan": {"han": {"Diêm Vương": {"desc": "Hạn Diêm Vương là hạn đặc biệt kỵ với phụ nữ, nhất là phụ nữ đang mang thai và sinh nở, cần hết sức giữ gìn sức khỏe trong thai kỳ. Ngược lại, nam giới gặp hạn này theo quan niệm dân gian lại khá thuận lợi về làm ăn, buôn bán, nhưng vẫn không nên chủ quan về sức khỏe của người thân nữ trong nhà.", "type": "xấu"}, "Huỳnh Tuyền": {"desc": "Hạn Huỳnh Tuyền là đại hạn chủ về bệnh tật nặng liên quan đến đầu và thần kinh, dễ đau đầu, chóng mặt, xây xẩm và kỵ các việc liên quan đến sông nước. Người gặp hạn này cần chăm sóc sức khỏe cẩn thận, không nên đứng ra bảo lãnh, chứng thực giấy tờ cho người khác.", "type": "xấu"}, "Ngũ Mộ": {"desc": "Hạn Ngũ Mộ là tiểu hạn chủ về hao tài tốn của, dễ mất mát tiền bạc, bị lừa gạt khi mua bán hoặc cho vay mượn không đòi lại được. Người gặp hạn này tuyệt đối không nên cho người khác ngủ nhờ, gửi đồ quý trong nhà và cần kiểm tra kỹ giấy tờ khi giao dịch tiền bạc.", "type": "xấu"}, "Tam Kheo": {"desc": "Hạn Tam Kheo là tiểu hạn chủ về thương tích ở tay chân và các bệnh về mắt, dễ bị té ngã, va chạm hoặc đau nhức xương khớp. Người gặp hạn này nên cẩn thận khi đi lại, lao động và hạn chế đến nơi đông người chen lấn, đồng thời chú ý giữ gìn đôi mắt.", "type": "xấu"}, "Thiên La": {"desc": "Hạn Thiên La là hạn chủ về gia đạo bất an, tâm lý bất ổn, dễ mất ngủ, lo âu và vướng chuyện tình cảm, vợ chồng lục đục. Người gặp hạn này nên giữ cuộc sống sinh hoạt điều độ, tránh thức khuya, tu tâm dưỡng tính và nhường nhịn trong gia đình để mọi việc êm thấm.", "type": "xấu"}, "Thiên Tinh": {"desc": "Hạn Thiên Tinh là hạn chủ về ngộ độc thực phẩm, bệnh đường ruột và dễ vướng thị phi, kiện tụng do lời nói vô tình gây ra. Người gặp hạn này phải hết sức cẩn trọng trong ăn uống, tránh ăn đồ lạ ngoài đường và giữ gìn lời ăn tiếng nói để không rước họa vào thân.", "type": "xấu"}, "Toán Tận": {"desc": "Hạn Toán Tận là đại hạn chủ về hao tài bất ngờ và tai nạn khi di chuyển, tiền bạc dễ đội nón ra đi vì những sự cố ngoài ý muốn. Người gặp hạn này không nên mang theo nhiều tiền và đồ quý khi ra đường, cẩn trọng khi đi đường dài, đường rừng núi và chung vốn làm ăn với người khác.", "type": "xấu"}, "Địa Võng": {"desc": "Hạn Địa Võng là hạn chủ về thị phi, tranh cãi và kiện tụng, dễ bị hiểu lầm, vướng vào chuyện rắc rối của người khác và kỵ đi lại vào giờ Tuất buổi tối. Người gặp hạn này không nên đứng ra can thiệp chuyện bao đồng, tránh cho người lạ ở nhờ và giữ giấy tờ tùy thân, hợp đồng thật cẩn thận.", "type": "xấu"}}, "sao": {"Kế Đô": {"desc": "Sao Kế Đô là hung tinh chủ về buồn phiền, thị phi và tai ách bất ngờ, nữ giới gặp sao này thường nặng hơn nam giới, dễ sinh chuyện buồn trong gia đạo. Người có sao Kế Đô chiếu nên hạn chế đi xa và giữ tâm lý ổn định, cẩn trọng nhất vào tháng Ba và tháng Chín âm lịch.", "offering": "Cúng giải hạn vào ngày 18 âm lịch hằng tháng, từ 21 giờ đến 23 giờ, thắp 20 ngọn đèn hoặc nến, bài vị màu vàng ghi danh tính sao Kế Đô, lễ vật hướng về phía Tây mà lạy 20 lạy.", "type": "xấu"}, "La Hầu": {"desc": "Sao La Hầu là hung tinh chủ về thị phi, khẩu thiệt, dễ vướng tranh cãi, kiện tụng và hao tốn vì lời ăn tiếng nói. Nam giới gặp sao này thường nặng hơn nữ, nhất là vào tháng Giêng và tháng Bảy âm lịch, cần giữ mồm giữ miệng và tránh rượu chè quá chén.", "offering": "Cúng giải hạn vào ngày 8 âm lịch hằng tháng (tập trung tháng Giêng), từ 21 giờ đến 23 giờ, thắp 9 ngọn đèn hoặc nến, bài vị màu đỏ ghi danh tính sao La Hầu, lễ vật hướng về phía Bắc mà lạy 9 lạy.", "type": "xấu"}, "Mộc Đức": {"desc": "Sao Mộc Đức là cát tinh chủ về may mắn, hỷ sự, hòa khí trong gia đạo và quý nhân phù trợ, rất tốt cho việc cưới hỏi và làm ăn buôn bán. Nam nữ gặp sao này đều thuận lợi, song nam giới vẫn nên đề phòng bệnh về mắt, tốt nhất và hỷ sự nhiều nhất vào tháng Mười và tháng Chạp âm lịch.", "offering": "Cúng nghênh sao vào ngày 25 âm lịch hằng tháng, từ 19 giờ đến 21 giờ, thắp 20 ngọn đèn hoặc nến, bài vị màu xanh ghi danh tính sao Mộc Đức, lễ vật hướng về phía Đông mà lạy 20 lạy.", "type": "tốt"}, "Thái Bạch": {"desc": "Sao Thái Bạch là hung tinh nặng nhất trong chín sao, chủ về hao tài tốn của, dễ mất tiền bạc, bị tiểu nhân hãm hại và công việc làm ăn trắc trở. Người gặp sao này cần hết sức thận trọng trong chi tiêu và đầu tư, kỵ nhất tháng Năm âm lịch, tránh mặc đồ trắng suốt tháng đó theo quan niệm dân gian.", "offering": "Cúng giải hạn vào ngày 15 âm lịch hằng tháng, từ 19 giờ đến 21 giờ, thắp 8 ngọn đèn hoặc nến, bài vị màu trắng ghi danh tính sao Thái Bạch, lễ vật hướng về phía Tây mà lạy 8 lạy.", "type": "xấu"}, "Thái Dương": {"desc": "Sao Thái Dương là cát tinh tốt nhất cho nam giới, chủ về công danh, thăng quan tiến chức, làm ăn phát đạt và tiếng tăm vang xa. Nữ giới gặp sao này thì công việc cũng thuận lợi nhưng nhẹ hơn nam, cả hai đều nên tận dụng năm có sao này chiếu để mở mang sự nghiệp, tốt nhất vào tháng Sáu và tháng Mười âm lịch.", "offering": "Cúng nghênh sao vào ngày 27 âm lịch hằng tháng, từ 21 giờ đến 23 giờ, thắp 12 ngọn đèn hoặc nến, bài vị màu vàng ghi danh tính sao Thái Dương, lễ vật hướng về phía Đông mà lạy 12 lạy.", "type": "tốt"}, "Thái Âm": {"desc": "Sao Thái Âm là cát tinh chủ về tài lộc, danh vọng và sự giúp đỡ của quý nhân, đặc biệt tốt cho nữ giới và những người làm công việc liên quan đến đất đai, tiền bạc. Mọi việc trong năm có sao này chiếu thường hanh thông, tốt nhất vào tháng Chín âm lịch, song tháng Mười Một cần đề phòng bệnh tật vặt.", "offering": "Cúng nghênh sao vào ngày 26 âm lịch hằng tháng, từ 19 giờ đến 21 giờ, thắp 7 ngọn đèn hoặc nến, bài vị màu vàng ghi danh tính sao Thái Âm, lễ vật hướng về phía Tây mà lạy 7 lạy.", "type": "tốt"}, "Thổ Tú": {"desc": "Sao Thổ Tú là hung tinh chủ về tiểu nhân quấy phá, dễ bị gièm pha, cản trở công việc và kỵ đi xa, xuất hành xa nhà. Người gặp sao này nên cẩn trọng trong các tháng Tư và tháng Tám âm lịch, hạn chế tranh chấp đất đai và đề phòng sức khỏe đường tiêu hóa.", "offering": "Cúng giải hạn vào ngày 19 âm lịch hằng tháng, từ 20 giờ đến 22 giờ, thắp 5 ngọn đèn hoặc nến, bài vị màu vàng ghi danh tính sao Thổ Tú, lễ vật hướng về phía Tây mà lạy 5 lạy.", "type": "xấu"}, "Thủy Diệu": {"desc": "Sao Thủy Diệu là sao vừa có mặt tốt vừa có mặt xấu, chủ về tài lộc liên quan đến nước và đi lại, nhưng cũng dễ gặp thị phi, mất mát nhỏ và bất lợi khi qua sông, đi biển. Nữ giới gặp sao này cần cẩn trọng lời nói, nam giới thì tương đối thuận lợi hơn, kỵ nhất tháng Tư và tháng Tám âm lịch.", "offering": "Cúng giải hạn hoặc nghênh sao vào ngày 21 âm lịch hằng tháng, từ 19 giờ đến 21 giờ, thắp 7 ngọn đèn hoặc nến, bài vị màu đen ghi danh tính sao Thủy Diệu, lễ vật hướng về phía Bắc mà lạy 7 lạy.", "type": "trung tính"}, "Vân Hán": {"desc": "Sao Vân Hán, còn gọi là Vân Hớn, là sao trung tính nghiêng về mặt cần đề phòng: công việc làm ăn ở mức trung bình nhưng dễ vướng thị phi, kiện tụng và bệnh tật liên quan đến máu huyết, nóng trong người. Người gặp sao này nên giữ tính khí ôn hòa, cẩn trọng nhất vào tháng Hai và tháng Tám âm lịch, phụ nữ mang thai cần đặc biệt chú ý sức khỏe.", "offering": "Cúng giải hạn vào ngày 29 âm lịch hằng tháng, từ 19 giờ đến 21 giờ, thắp 15 ngọn đèn hoặc nến, bài vị màu đỏ ghi danh tính sao Vân Hán, lễ vật hướng về phía Nam mà lạy 15 lạy.", "type": "trung tính"}}}, "thanSoHoc": {"lifePathNote": "Số chủ đạo được tính bằng cách cộng rút gọn ngày tháng năm sinh dương lịch, phản ánh xu hướng tính cách và bài học lớn của cả cuộc đời chứ không phải định mệnh cố định.", "numbers": {"1": {"career": "Hợp với các nghề cần tính tự chủ cao như quản lý, kinh doanh, khởi nghiệp, kỹ sư trưởng hoặc bất kỳ vị trí nào được toàn quyền chịu trách nhiệm.", "love": "Trong tình cảm bạn chủ động và thẳng thắn, thích một mối quan hệ rõ ràng, nhưng cần tiết chế tính chiếm hữu để đối phương không thấy ngột ngạt.", "name": "Số 1, Số chủ đạo của người dẫn đầu", "traits": "Bạn mang năng lượng của người mở đường: quyết đoán, độc lập và luôn muốn tự mình làm chủ cuộc chơi. Điểm mạnh là ý chí bền bỉ, dám nghĩ dám làm và rất nhanh nhạy khi phải đưa ra quyết định. Điểm yếu là đôi lúc nóng vội, khó lắng nghe ý kiến trái chiều và dễ tự tạo áp lực phải đứng nhất. Học cách chia sẻ quyền quyết định sẽ giúp bạn đi xa hơn nhiều."}, "11": {"career": "Hợp với nghề tư vấn tâm lý, chữa lành, nghệ thuật, giảng dạy hoặc các công việc truyền cảm hứng và khai mở tiềm năng con người.", "love": "Bạn cần một mối quan hệ có sự thấu hiểu ở tầng sâu, nơi hai người kết nối bằng tâm hồn chứ không chỉ bằng sự hấp dẫn bề ngoài.", "name": "Số 11, Số bậc thầy của trực giác", "traits": "Đây là con số bậc thầy với trực giác nhạy bén và đời sống tinh thần sâu sắc hơn người thường. Bạn dễ đồng cảm, có khả năng cảm nhận điều người khác chưa nói ra và thường có sức hút lạ kỳ. Điểm yếu là cảm xúc lên xuống thất thường, dễ căng thẳng và tự nghi ngờ chính mình. Khi học được cách lắng nghe trực giác mà vẫn giữ đôi chân trên mặt đất, bạn sẽ trở thành người dẫn dắt tinh thần cho nhiều người."}, "2": {"career": "Hợp với nghề tư vấn, nhân sự, chăm sóc khách hàng, giáo dục, y tế hoặc các công việc đứng sau hỗ trợ để cả tập thể cùng tỏa sáng.", "love": "Bạn yêu bằng sự dịu dàng và chung thủy, luôn ưu tiên hòa khí, nhưng nên tránh hy sinh quá mức khiến bản thân thiệt thòi trong mối quan hệ.", "name": "Số 2, Số chủ đạo của người hòa giải", "traits": "Bạn là người nhạy cảm, tinh tế và có khả năng lắng nghe hiếm có, luôn biết đặt mình vào vị trí của người khác. Điểm mạnh nằm ở sự khéo léo trong ngoại giao, kiên nhẫn và biết dung hòa mâu thuẫn. Điểm yếu là dễ cả nể, ngại từ chối và hay giấu cảm xúc thật của mình. Khi học được cách nói ra nhu cầu của bản thân, bạn sẽ vững vàng hơn hẳn."}, "22": {"career": "Hợp với nghề kiến trúc, quy hoạch, điều hành tổ chức lớn, khởi nghiệp xã hội hoặc bất kỳ lĩnh vực nào cần tầm nhìn dài hạn và năng lực tổ chức quy mô.", "love": "Bạn tìm kiếm một người bạn đời đồng chí hướng, cùng xây dựng sự nghiệp và lý tưởng sống, tình cảm vì thế thường bền chặt theo năm tháng.", "name": "Số 22, Số bậc thầy của người kiến tạo", "traits": "Đây là con số bậc thầy mạnh nhất trong thần số học, kết hợp tầm nhìn lớn của người mơ mộng với năng lực thực thi của người xây dựng. Bạn có khả năng biến những ý tưởng tưởng chừng viển vông thành công trình và giá trị thật cho xã hội. Điểm yếu là áp lực tự đặt lên vai quá lớn, dễ kiệt sức và thất vọng khi kết quả chưa xứng tầm kỳ vọng. Chia nhỏ mục tiêu và kiên nhẫn từng bước, bạn sẽ dựng được những điều bền vững."}, "3": {"career": "Hợp với nghề truyền thông, marketing, nghệ thuật, dẫn chương trình, bán hàng hoặc bất kỳ công việc nào cần sự sáng tạo và giao tiếp.", "love": "Bạn lãng mạn và biết cách làm mới tình cảm, thu hút người khác bằng sự vui tươi, nhưng cần sự nghiêm túc và ổn định khi muốn đi đường dài.", "name": "Số 3, Số chủ đạo của người truyền cảm hứng", "traits": "Bạn sôi nổi, hoạt bát và có óc sáng tạo tự nhiên, đi đến đâu cũng mang theo tiếng cười và ý tưởng mới. Điểm mạnh là khả năng diễn đạt cuốn hút, lạc quan và dễ kết nối với mọi người. Điểm yếu là thiếu kiên nhẫn với việc lặp lại, dễ chán và đôi khi nói nhanh hơn nghĩ. Rèn tính kỷ luật với những việc nhỏ sẽ biến tài năng của bạn thành thành quả thật."}, "4": {"career": "Hợp với nghề kỹ thuật, xây dựng, kế toán, quản lý vận hành, công nghệ thông tin hoặc các công việc đòi hỏi quy trình và độ chính xác cao.", "love": "Bạn yêu chậm mà chắc, không thích phô trương nhưng luôn ở bên khi người kia cần, chỉ cần học cách bộc lộ cảm xúc nhiều hơn một chút.", "name": "Số 4, Số chủ đạo của người xây nền móng", "traits": "Bạn thực tế, ngăn nắp và cực kỳ đáng tin cậy, việc gì giao vào tay bạn cũng được làm đến nơi đến chốn. Điểm mạnh là kỷ luật, kiên trì và tư duy hệ thống rõ ràng. Điểm yếu là hơi cứng nhắc, ngại thay đổi và dễ ôm đồm chi tiết vụn vặt. Thỉnh thoảng cho phép mình linh hoạt và nghỉ ngơi, bạn sẽ làm việc hiệu quả hơn nhiều."}, "5": {"career": "Hợp với nghề du lịch, thương mại, truyền thông số, sự kiện, kinh doanh tự do hoặc các công việc được di chuyển và gặp gỡ nhiều người.", "love": "Bạn bị thu hút bởi sự mới mẻ và thú vị, cần một người bạn đời vừa là người yêu vừa là bạn đồng hành khám phá cuộc sống.", "name": "Số 5, Số chủ đạo của người tự do", "traits": "Bạn yêu tự do, thích trải nghiệm và luôn tò mò với những điều mới lạ, khó ai giữ chân được bạn trong một khuôn khổ chật hẹp. Điểm mạnh là khả năng thích nghi nhanh, tư duy mở và tràn đầy năng lượng. Điểm yếu là dễ phân tâm, thiếu cam kết lâu dài và đôi khi hành động bốc đồng. Khi tìm được một mục tiêu đủ lớn để dồn sức, bạn sẽ tiến rất nhanh."}, "6": {"career": "Hợp với nghề giáo dục, y tế, tư vấn gia đình, ẩm thực, thiết kế nội thất hoặc các công việc chăm sóc và phục vụ cộng đồng.", "love": "Bạn yêu với mong muốn xây dựng tổ ấm nghiêm túc, chung thủy và biết hy sinh, chỉ cần tránh kiểm soát quá mức người mình thương.", "name": "Số 6, Số chủ đạo của người chăm sóc", "traits": "Bạn ấm áp, trách nhiệm và luôn đặt gia đình cùng những người thân yêu lên hàng đầu. Điểm mạnh là sự tận tâm, đáng tin và khả năng vun vén để mọi người xung quanh thấy an yên. Điểm yếu là hay lo xa, dễ ôm việc của người khác vào mình và có xu hướng cầu toàn trong chuyện nhà cửa. Học cách buông bớt và tin tưởng người thân sẽ giúp bạn nhẹ lòng hơn."}, "7": {"career": "Hợp với nghề nghiên cứu, phân tích dữ liệu, tâm lý học, triết học, công nghệ hoặc các công việc chuyên sâu cần sự tập trung cao độ.", "love": "Bạn yêu chậm, kén chọn và cần nhiều không gian riêng, nhưng một khi đã mở lòng thì tình cảm rất sâu đậm và bền vững.", "name": "Số 7, Số chủ đạo của người chiêm nghiệm", "traits": "Bạn sâu sắc, ham học hỏi và có đời sống nội tâm phong phú, luôn muốn hiểu tới tận cùng bản chất của mọi việc. Điểm mạnh là tư duy phân tích, trực giác tốt và khả năng tự học bền bỉ. Điểm yếu là khép kín, khó mở lòng và đôi lúc đa nghi quá mức cần thiết. Dành thời gian chia sẻ với người tin cậy sẽ giúp bạn cân bằng giữa lý trí và cảm xúc."}, "8": {"career": "Hợp với nghề quản trị, tài chính, đầu tư, bất động sản, kinh doanh quy mô lớn hoặc các vị trí lãnh đạo cần tầm nhìn dài hạn.", "love": "Bạn yêu người có chí hướng và độc lập, thể hiện tình cảm bằng hành động thiết thực hơn lời nói, nhưng nên dành thời gian chất lượng cho đối phương.", "name": "Số 8, Số chủ đạo của người điều hành", "traits": "Bạn tham vọng, thực tế và có đầu óc tổ chức cùng khả năng nhìn ra cơ hội làm ăn từ rất sớm. Điểm mạnh là quyết đoán, chịu áp lực tốt và biết dùng nguồn lực một cách hiệu quả. Điểm yếu là dễ đặt công việc lên trên mọi thứ, đôi khi thẳng thắn đến mức làm người khác tổn thương. Khi biết cân bằng giữa thành tựu và đời sống tình cảm, bạn sẽ thực sự viên mãn."}, "9": {"career": "Hợp với nghề từ thiện, xã hội, nghệ thuật, giáo dục, y tế cộng đồng hoặc các công việc mang sứ mệnh phụng sự con người.", "love": "Bạn yêu chân thành và vị tha, sẵn sàng cho đi rất nhiều, chỉ cần tỉnh táo để không bị lợi dụng lòng tốt trong chuyện tình cảm.", "name": "Số 9, Số chủ đạo của người nhân ái", "traits": "Bạn bao dung, giàu lòng trắc ẩn và luôn nghĩ cho cộng đồng trước khi nghĩ cho riêng mình. Điểm mạnh là sự tử tế, lý tưởng sống cao đẹp và khả năng truyền cảm hứng cho người khác. Điểm yếu là dễ mơ mộng xa rời thực tế, hay ôm nỗi buồn của thiên hạ và khó buông bỏ chuyện đã qua. Học cách chăm sóc chính mình trước sẽ giúp bạn giúp được nhiều người hơn."}}}, "zodiac": [{"career": "Hợp với công việc cần sự tiên phong và quyết đoán như kinh doanh, thể thao, quân sự, kỹ thuật hoặc vị trí trưởng nhóm.", "dates": "21/3 - 19/4", "element": "Lửa", "love": "Bạn yêu mãnh liệt và chủ động theo đuổi, thích sự thẳng thắn rõ ràng, nhưng nên học cách lắng nghe thay vì luôn giành phần thắng trong tranh luận.", "lucky": "Màu may mắn: đỏ và cam; con số may mắn: 1, 9.", "sign": "Bạch Dương", "traits": "Bạch Dương nhiệt huyết, thẳng thắn và luôn là người xông pha đầu tiên trong mọi việc. Bạn ghét sự vòng vo, thích hành động nhanh và dám chịu trách nhiệm với quyết định của mình. Điểm cần lưu ý là tính nóng vội và thiếu kiên nhẫn khi mọi chuyện diễn ra chậm hơn mong đợi. Khi biết kiềm chế cơn bốc đồng, nguồn năng lượng dồi dào của bạn sẽ đưa bạn đi rất xa."}, {"career": "Hợp với công việc trong tài chính, ngân hàng, bất động sản, ẩm thực, nông nghiệp hoặc nghệ thuật thủ công cần sự tỉ mỉ.", "dates": "20/4 - 20/5", "element": "Đất", "love": "Bạn yêu bền bỉ và chung thủy, thể hiện tình cảm bằng sự chăm sóc thiết thực, chỉ cần tránh tính sở hữu khiến đối phương cảm thấy bị gò bó.", "lucky": "Màu may mắn: xanh lá và hồng; con số may mắn: 2, 6.", "sign": "Kim Ngưu", "traits": "Kim Ngưu điềm đạm, kiên định và có gu thẩm mỹ cùng khả năng quản lý tiền bạc rất chắc tay. Bạn làm việc chậm mà chắc, đã hứa là làm và luôn hướng tới sự ổn định lâu dài. Điểm cần lưu ý là tính bướng bỉnh và ngại thay đổi khi đã quen với một nếp sống. Mở lòng với những trải nghiệm mới sẽ giúp cuộc sống của bạn phong phú hơn nhiều."}, {"career": "Hợp với công việc truyền thông, báo chí, marketing, thương mại, giảng dạy hoặc nghề cần ngoại ngữ và giao tiếp đa dạng.", "dates": "21/5 - 20/6", "element": "Khí", "love": "Bạn bị thu hút bởi người thông minh và thú vị trong trò chuyện, cần một mối quan hệ nhiều màu sắc hơn là sự lãng mạn đơn điệu.", "lucky": "Màu may mắn: vàng và xanh nhạt; con số may mắn: 3, 5.", "sign": "Song Tử", "traits": "Song Tử nhanh nhẹn, tò mò và có tài ăn nói cùng khả năng học hỏi nhiều lĩnh vực cùng lúc. Bạn thích giao tiếp, sợ sự nhàm chán và luôn cần những câu chuyện mới để nuôi dưỡng đầu óc. Điểm cần lưu ý là sự thiếu tập trung và dễ thay đổi ý định giữa chừng. Khi chọn một hướng đi và đào sâu tới cùng, bạn sẽ gặt hái được thành quả xứng đáng với trí tuệ của mình."}, {"career": "Hợp với công việc chăm sóc, y tế, giáo dục mầm non, tâm lý, ẩm thực hoặc kinh doanh những gì liên quan đến gia đình và nhà ở.", "dates": "21/6 - 22/7", "element": "Nước", "love": "Bạn yêu bằng cả trái tim và mong muốn xây dựng tổ ấm nghiêm túc, cần một người biết trân trọng sự dịu dàng và chung thủy của bạn.", "lucky": "Màu may mắn: trắng bạc và xanh biển; con số may mắn: 2, 7.", "sign": "Cự Giải", "traits": "Cự Giải giàu tình cảm, trực giác nhạy và luôn là chỗ dựa ấm áp cho gia đình cùng bạn bè thân thiết. Bạn nhớ rất lâu những điều nhỏ nhặt, cả điều tốt lẫn những tổn thương cũ. Điểm cần lưu ý là xu hướng khép mình khi buồn và để cảm xúc chi phối quyết định. Học cách nói ra điều mình cần thay vì chờ người khác tự hiểu sẽ giúp bạn nhẹ lòng hơn."}, {"career": "Hợp với công việc nghệ thuật biểu diễn, quản lý, quan hệ công chúng, sự kiện hoặc bất kỳ vị trí lãnh đạo nào cần sự hiện diện mạnh mẽ.", "dates": "23/7 - 22/8", "element": "Lửa", "love": "Bạn yêu nồng nhiệt và thích được ngưỡng mộ, hào phóng với người mình thương, nhưng nên nhường phần spotlight cho đối phương đôi lúc.", "lucky": "Màu may mắn: vàng kim và cam; con số may mắn: 1, 5.", "sign": "Sư Tử", "traits": "Sư Tử tự tin, hào phóng và sinh ra để đứng ở vị trí trung tâm với phong thái đầy cuốn hút. Bạn sống nhiệt thành, trọng danh dự và luôn sẵn sàng che chở cho người yếu thế hơn. Điểm cần lưu ý là cái tôi lớn và nhu cầu được công nhận đôi khi khiến bạn khó chấp nhận lời chê. Khi dùng sức ảnh hưởng để nâng đỡ người khác thay vì chỉ để tỏa sáng một mình, bạn sẽ được kính trọng thật sự."}, {"career": "Hợp với công việc phân tích, biên tập, y tế, kế toán, kiểm định chất lượng hoặc nghiên cứu cần độ chính xác cao.", "dates": "23/8 - 22/9", "element": "Đất", "love": "Bạn yêu bằng sự quan tâm thầm lặng và những việc làm cụ thể, kén chọn trong tình cảm nhưng một khi đã chọn thì rất nghiêm túc và bền lâu.", "lucky": "Màu may mắn: xanh rêu và be; con số may mắn: 3, 6.", "sign": "Xử Nữ", "traits": "Xử Nữ tỉ mỉ, logic và có con mắt nhìn ra lỗi sai mà người khác bỏ qua. Bạn làm việc có kế hoạch, đáng tin và luôn muốn mọi thứ hoàn thiện hơn hôm qua một chút. Điểm cần lưu ý là tính cầu toàn dễ biến thành soi xét bản thân và người khác quá mức. Học cách chấp nhận rằng không hoàn hảo cũng là một phần của cuộc sống sẽ giúp bạn bớt căng thẳng."}, {"career": "Hợp với công việc ngoại giao, luật, thiết kế, thời trang, tư vấn hoặc nghề cần đàm phán và con mắt thẩm mỹ.", "dates": "23/9 - 22/10", "element": "Khí", "love": "Bạn là người lãng mạn và tinh tế trong tình yêu, tìm kiếm sự hòa hợp lâu dài, chỉ cần tránh né tránh mâu thuẫn khiến vấn đề tích tụ dần.", "lucky": "Màu may mắn: hồng phấn và xanh pastel; con số may mắn: 6, 9.", "sign": "Thiên Bình", "traits": "Thiên Bình duyên dáng, công bằng và có khả năng cân bằng các mối quan hệ một cách khéo léo hiếm có. Bạn yêu cái đẹp, ghét xung đột và luôn cân nhắc mọi phía trước khi quyết định. Điểm cần lưu ý là sự do dự kéo dài và thói quen chiều lòng người khác mà quên mất mình muốn gì. Tin vào cảm nhận đầu tiên của bản thân sẽ giúp bạn quyết đoán hơn."}, {"career": "Hợp với công việc điều tra, tài chính, y khoa, tâm lý, nghiên cứu hoặc lĩnh vực cần sự tập trung và giữ bí mật tốt.", "dates": "23/10 - 21/11", "element": "Nước", "love": "Bạn yêu sâu đậm và mãnh liệt, đòi hỏi sự chung thủy tuyệt đối, cần một người đủ chân thành để bạn yên tâm mở lòng.", "lucky": "Màu may mắn: đỏ sẫm và đen; con số may mắn: 8, 9.", "sign": "Bọ Cạp", "traits": "Bọ Cạp sâu sắc, bí ẩn và có ý chí mạnh mẽ cùng khả năng nhìn thấu tâm tư người khác. Bạn làm gì cũng dồn hết tâm sức, ghét sự hời hợt và rất trọng lời hứa. Điểm cần lưu ý là tính đa nghi và thói quen giữ kín mọi cảm xúc cho đến khi bùng nổ. Học cách tin tưởng và tha thứ sẽ giải phóng cho bạn rất nhiều năng lượng bị dồn nén."}, {"career": "Hợp với công việc du lịch, giáo dục, xuất bản, thể thao, thương mại quốc tế hoặc nghề được đi nhiều và học nhiều.", "dates": "22/11 - 21/12", "element": "Lửa", "love": "Bạn cần một người bạn đời vừa là người yêu vừa là bạn đồng hành phiêu lưu, sợ nhất cảm giác bị kiểm soát trong tình cảm.", "lucky": "Màu may mắn: tím và xanh dương; con số may mắn: 3, 9.", "sign": "Nhân Mã", "traits": "Nhân Mã lạc quan, phóng khoáng và luôn hướng về những chân trời mới với tinh thần khám phá bất tận. Bạn thẳng thắn, hài hước và truyền được niềm vui sống cho người xung quanh một cách tự nhiên. Điểm cần lưu ý là sự thiếu kiên nhẫn với chi tiết và đôi khi nói thẳng quá mức làm người nghe phật ý. Khi gắn sự tự do của mình với một mục đích rõ ràng, bạn sẽ tiến xa mà không thấy bị ràng buộc."}, {"career": "Hợp với công việc quản trị, kỹ thuật, tài chính, luật hoặc bất kỳ con đường sự nghiệp nào cần thăng tiến từng bậc vững chắc.", "dates": "22/12 - 19/1", "element": "Đất", "love": "Bạn yêu nghiêm túc với định hướng lâu dài, thể hiện tình cảm bằng sự ổn định và đáng tin cậy hơn là lời đường mật.", "lucky": "Màu may mắn: nâu và xám đậm; con số may mắn: 8, 10.", "sign": "Ma Kết", "traits": "Ma Kết tham vọng, kỷ luật và là người leo núi bền bỉ nhất trong mười hai cung, không ngại đi đường dài để tới đỉnh. Bạn thực tế, có trách nhiệm và xây dựng sự nghiệp bằng năng lực thật chứ không dựa vào may rủi. Điểm cần lưu ý là xu hướng ôm hết việc, khó thư giãn và hiếm khi để lộ mặt yếu đuối của mình. Cho phép bản thân nghỉ ngơi và tận hưởng thành quả sẽ giúp bạn đi đường dài bền hơn."}, {"career": "Hợp với công việc công nghệ, khoa học, hoạt động xã hội, sáng tạo nội dung hoặc lĩnh vực đổi mới cần tư duy đột phá.", "dates": "20/1 - 18/2", "element": "Khí", "love": "Bạn tìm kiếm sự kết nối về trí tuệ và lý tưởng sống, cần không gian riêng ngay cả khi đang yêu, và trân trọng người tôn trọng sự khác biệt của bạn.", "lucky": "Màu may mắn: xanh ngọc và bạc; con số may mắn: 4, 7.", "sign": "Bảo Bình", "traits": "Bảo Bình độc đáo, nhân văn và luôn đi trước thời đại với những ý tưởng không giống ai. Bạn coi trọng tự do tư tưởng, thích kết nối cộng đồng và ghét những lối mòn áp đặt. Điểm cần lưu ý là đôi khi bạn sống trong thế giới ý tưởng mà xa rời cảm xúc thực tế của người gần mình nhất. Học cách hiện diện và lắng nghe bằng trái tim sẽ giúp các mối quan hệ của bạn ấm áp hơn."}, {"career": "Hợp với công việc nghệ thuật, âm nhạc, điện ảnh, y tế chữa lành, tâm linh hoặc nghề cần sự sáng tạo và lòng trắc ẩn.", "dates": "19/2 - 20/3", "element": "Nước", "love": "Bạn yêu lãng mạn và hết lòng như trong cổ tích, sẵn sàng hy sinh vì người thương, nhưng cần tỉnh táo để không đánh mất chính mình.", "lucky": "Màu may mắn: xanh biển nhạt và tím lavender; con số may mắn: 7, 12.", "sign": "Song Ngư", "traits": "Song Ngư mơ mộng, nhân hậu và có tâm hồn nghệ sĩ cùng khả năng đồng cảm sâu sắc với nỗi niềm của người khác. Bạn sống bằng cảm xúc, giàu trí tưởng tượng và thường tìm thấy ý nghĩa trong những điều nhỏ bé. Điểm cần lưu ý là ranh giới cảm xúc mong manh khiến bạn dễ bị ảnh hưởng bởi tâm trạng của môi trường xung quanh. Học cách nói lời từ chối và dành thời gian tĩnh lặng cho riêng mình sẽ giúp bạn giữ được sự bình yên."}], "tienKiep": {"futurePaths": [{"desc": "Hậu vận của bạn nghiêng về sự an yên trong tâm hồn, càng lớn tuổi càng biết buông bỏ và sống chậm lại. Con đường này hợp với người biết tu dưỡng, làm việc thiện lặng lẽ và tìm niềm vui trong những điều giản dị.", "path": "Đường tu tâm hướng thiện"}, {"desc": "Nửa sau cuộc đời là thời kỳ bạn gặt hái thành quả từ nhiều năm gây dựng sự nghiệp, với vị thế và tiếng nói ngày càng được trọng vọng. Chìa khóa là giữ sức khỏe và biết chia sẻ quyền lực đúng lúc.", "path": "Đường công danh viên mãn"}, {"desc": "Hậu vận của bạn gắn với gia đình đông đủ, con cháu hiếu thuận và là chỗ dựa tinh thần cho cả nhà. Những năm tháng sau này quý nhất ở sự sum vầy và những bữa cơm có đủ mặt người thân.", "path": "Đường gia đạo sum vầy"}, {"desc": "Bạn có xu hướng về già càng làm càng có lộc, tài sản tích lũy đều đặn nhờ kinh nghiệm và uy tín lâu năm. Cần tránh đầu tư mạo hiểm ở tuổi xế chiều và ưu tiên những kênh an toàn, bền vững.", "path": "Đường tài lộc hậu thuẫn"}, {"desc": "Hậu vận mở ra một hành trình khám phá mới, có thể là đi xa, học một lĩnh vực hoàn toàn mới hoặc thay đổi môi trường sống. Tinh thần ham học hỏi giúp bạn trẻ lâu hơn tuổi thật rất nhiều.", "path": "Đường vân du học hỏi"}, {"desc": "Về sau bạn trở thành người truyền lại kinh nghiệm, được lớp trẻ tìm đến xin lời khuyên và học hỏi. Giá trị lớn nhất của hậu vận này nằm ở di sản tinh thần bạn để lại cho người khác.", "path": "Đường truyền nghề dẫn lối"}, {"desc": "Hậu vận của bạn gắn với các hoạt động cộng đồng, thiện nguyện và giúp đỡ những hoàn cảnh khó khăn hơn mình. Cho đi đúng cách khiến những năm tháng cuối đời của bạn nhẹ nhõm và ý nghĩa.", "path": "Đường phụng sự cộng đồng"}, {"desc": "Nửa sau đời người mang đến cho bạn một ngã rẽ bất ngờ, có thể là nghề tay trái thành nghề chính hoặc một mối duyên muộn đầy thấu hiểu. Đừng ngại bắt đầu lại, vì đây chính là đoạn đời bạn sống thật nhất với mình.", "path": "Đường tái sinh đổi vận"}, {"desc": "Hậu vận của bạn là những ngày tháng yên ổn bên mảnh vườn, góc sân và thú vui điền viên xa rời ồn ào phố thị. Sự giàu có ở đây đo bằng sức khỏe, giấc ngủ ngon và tâm trí thảnh thơi.", "path": "Đường điền viên an nhàn"}, {"desc": "Bạn có duyên để lại dấu ấn bằng chữ nghĩa, nghệ thuật hoặc những tác phẩm được người đời sau nhắc tới. Hậu vận càng thanh thản thì cảm hứng sáng tạo của bạn càng tuôn chảy dồi dào.", "path": "Đường lưu danh văn nghiệp"}], "lessons": ["Bài học lớn nhất của bạn là học cách tha thứ, cho người khác và cho chính mình, vì oán giữ trong lòng chỉ làm nặng thêm hành trang của đời này.", "Bạn cần học cách nhận sự giúp đỡ thay vì luôn là người cho đi, bởi cân bằng giữa nhận và cho mới là dòng chảy lành mạnh của nghiệp lành.", "Đời này bạn được giao bài học về sự kiên nhẫn: những điều tốt đẹp nhất dành cho bạn thường đến chậm, nhưng đến đúng lúc bạn đủ trưởng thành để giữ chúng.", "Bài học của bạn nằm ở chữ tín: giữ lời hứa nhỏ cũng quan trọng như lời hứa lớn, và uy tín là tài sản không tiền nào mua lại được khi đã đánh mất.", "Bạn cần học cách yêu thương mà không chiếm hữu, để người mình thương được là chính họ, và tình cảm vì thế mới bền lâu.", "Đời này nhắc bạn về bài học buông bỏ vật chất: tiền bạc là phương tiện tốt nhưng là ông chủ tệ, đừng để nó quyết định mọi lựa chọn của bạn.", "Bài học của bạn là nói ra sự thật một cách tử tế, vì sự im lặng né tránh kéo dài thường gây ra những hiểu lầm lớn hơn cả lời nói thẳng.", "Bạn cần rèn sự kỷ luật với bản thân, vì tài năng mà thiếu bền bỉ thì cũng như hạt giống tốt gieo trên đất cạn không ai chăm.", "Đời này dạy bạn bài học về ranh giới: biết nói không đúng lúc là cách bạn bảo vệ năng lượng để còn giúp được người khác dài lâu.", "Bài học sâu nhất của bạn là chấp nhận sự vô thường: người đến người đi đều có lý do, và biết ơn thay vì níu kéo sẽ giúp tâm bạn nhẹ nhàng hơn."], "pastLives": [{"desc": "Kiếp trước bạn gắn bó với sách vở và bút nghiên, sống bằng tri thức và được kính trọng vì sự uyên bác. Dấu ấn để lại là thói quen suy nghĩ sâu xa, thích ghi chép và luôn tôn trọng người có học ở đời này.", "role": "Học giả triều đình"}, {"desc": "Bạn từng sống đời lênh đênh trên sông nước, rày đây mai đó theo những chuyến hàng và bến đỗ. Nhờ đó đời này bạn thích nghi nhanh, ham khám phá và khó chịu được một cuộc sống quá gò bó.", "role": "Thương nhân đường sông"}, {"desc": "Kiếp trước bạn là người trực tiếp trồng cấy, sống gần đất và hiểu rõ quy luật mùa vụ gieo gặt. Dư âm của kiếp đó là tính kiên nhẫn, yêu thiên nhiên và trân trọng những giá trị lao động chân chất.", "role": "Nông phu canh điền"}, {"desc": "Bạn từng khoác áo ra trận, sống trong kỷ luật sắt và tinh thần bảo vệ người khác. Đời này bạn thường có bản năng che chở kẻ yếu, quyết đoán trong khủng hoảng nhưng cần học cách sống mềm mại khi không còn chiến tuyến nào.", "role": "Võ tướng sa trường"}, {"desc": "Kiếp trước bạn hành nghề cứu người, quen thuộc với thảo dược, mạch tượng và nỗi đau của bệnh nhân. Đời này bạn dễ đồng cảm với người đang khổ, có trực giác tốt về sức khỏe và thường được tin cậy khi ai đó cần an ủi.", "role": "Thầy thuốc đông y"}, {"desc": "Bạn từng là bàn tay làm ra những sản phẩm tinh xảo, gửi cả tâm huyết vào từng đường chạm khắc. Dấu ấn còn lại là sự khéo léo, con mắt thẩm mỹ và niềm vui khi tự tay tạo ra một thứ gì đó hoàn chỉnh.", "role": "Thợ thủ công lành nghề"}, {"desc": "Kiếp trước bạn sống đời tu hành thanh tịnh, xa lánh bụi trần để tìm sự giác ngộ trong tĩnh lặng. Vì thế đời này bạn thường cần những khoảng lặng riêng, dễ rung động trước những câu hỏi lớn về ý nghĩa cuộc sống.", "role": "Tu sĩ ẩn tu"}, {"desc": "Bạn từng đứng trên sân khấu kể chuyện, ca hát hoặc diễn xướng làm vui cho bao người. Dư âm là khả năng ăn nói cuốn hút, trí nhớ tốt về câu chuyện và nhu cầu được lắng nghe, được thấu hiểu ở đời này.", "role": "Nghệ nhân dân gian"}, {"desc": "Kiếp trước bạn giữ vai trò quản việc của một cộng đồng, lo toan chuyện chung và đứng ra dàn xếp tranh chấp. Đời này bạn thường tự nhiên trở thành người tổ chức, được nhờ cậy khi tập thể cần một người công tâm đứng giữa.", "role": "Lý trưởng làng xã"}, {"desc": "Bạn từng dành cả đời chăm sóc một mái nhà đông người, là trung tâm gắn kết của gia đình nhiều thế hệ. Dấu ấn để lại là bản năng vun vén, nhớ sinh nhật và sở thích của từng người thân, cùng nỗi sợ vô hình trước sự chia lìa.", "role": "Người mẹ tảo tần"}, {"desc": "Kiếp trước bạn đi biển dài ngày, đối diện bão tố và sự mênh mông không bờ của đại dương. Đời này bạn gan dạ, chịu đựng giỏi trong nghịch cảnh và luôn tin rằng sau cơn sóng lớn nào cũng có bến bờ.", "role": "Ngư phủ vượt sóng"}, {"desc": "Bạn từng giữ trọng trách chép sử, ghi lại biến cố của thời đại cho hậu thế một cách trung thực. Dư âm là tính cẩn trọng với lời nói, thói quen lưu trữ ký ức và sự khó chịu khi thấy sự thật bị bóp méo ở đời này.", "role": "Sử quan chép sử"}]}, "hocVan": {"byCan": {"Bính": "Người can Bính học nhanh, tiếp thu mạnh mẽ và đặc biệt hứng thú khi được khám phá kiến thức mới mẻ. Đường học vấn rộng mở nếu biết duy trì sự tập trung, tránh học dồn dập theo hứng rồi bỏ dở giữa chừng.", "Canh": "Người can Canh tiếp thu kiến thức theo cách chắc chắn, thích đào sâu tới gốc rễ và giỏi các môn cần tư duy hệ thống. Học vấn của bạn thăng hoa khi chọn một chuyên ngành và theo đuổi đến cùng thay vì chạy theo trào lưu.", "Giáp": "Người can Giáp có tư duy vươn lên mạnh mẽ, học hành thiên về chiều sâu và rất hợp với con đường nghiên cứu lâu dài. Bạn học tốt nhất khi có mục tiêu rõ ràng và môi trường cạnh tranh lành mạnh để tự thúc đẩy mình.", "Kỷ": "Người can Kỷ học chậm mà chắc, nhớ lâu hiểu sâu và rất hợp với cách học tự ôn luyện kiên trì. Bạn dễ thành công ở những kỳ thi cần sự bền bỉ, chỉ cần thêm tự tin để dám thể hiện điều mình đã biết.", "Mậu": "Người can Mậu có nền tảng học vấn ổn định, tiếp thu đều ở nhiều lĩnh vực và giỏi biến kiến thức thành ứng dụng thực tế. Bạn hợp với con đường vừa học vừa làm, thành tích thường đến muộn nhưng rất bền vững.", "Nhâm": "Người can Nhâm thông minh linh hoạt, học rộng hiểu nhiều và có khả năng liên kết kiến thức giữa các lĩnh vực khác nhau. Đường học vấn của bạn thuận lợi khi đi vào nghiên cứu, ngoại ngữ hoặc những ngành cần tư duy mở và sáng tạo.", "Quý": "Người can Quý tiếp thu tinh tế, ghi nhớ tốt và đặc biệt có duyên với văn chương, ngôn ngữ và các môn xã hội. Bạn học hiệu quả trong không gian yên tĩnh, thành tích sẽ ổn định hơn khi bạn giữ nhịp học đều thay vì nước rút.", "Tân": "Người can Tân học hành tinh tế, chú trọng chi tiết và có năng khiếu ở các môn đòi hỏi sự chính xác như ngoại ngữ, kỹ thuật hoặc nghệ thuật. Bạn dễ đạt thành tích cao khi được học theo lộ trình rõ ràng và có người hướng dẫn tận tâm.", "Đinh": "Người can Đinh sáng dạ, có trực giác tốt trong học tập và đặc biệt nhạy bén với những môn cần cảm nhận tinh tế. Đường học của bạn cần sự bền chí, vì bạn học rất nhanh khi hứng thú nhưng cũng dễ nản khi gặp phần khô khan.", "Ất": "Người can Ất học tập mềm dẻo, tiếp thu tốt qua việc quan sát và bắt chước người giỏi xung quanh. Bạn hợp với các môn nghệ thuật, ngôn ngữ và xã hội, càng được khích lệ đúng cách thì thành tích càng đi lên rõ rệt."}, "byMenh": {"Hỏa": "Người mệnh Hỏa học bằng cảm hứng, bứt phá mạnh ở những giai đoạn nước rút và hợp với cách học theo dự án sôi nổi. Bạn cần rèn thói quen ôn tập đều đặn, vì phong độ thất thường là trở ngại lớn nhất trên đường học vấn.", "Kim": "Người mệnh Kim học hành có hệ thống, tư duy logic rõ ràng và ghi điểm tốt ở những môn cần phân tích chính xác. Bạn phát huy mạnh nhất khi tự đặt ra tiêu chuẩn cao và có kế hoạch ôn luyện chi tiết từng bước.", "Mộc": "Người mệnh Mộc ham học hỏi, tư duy phát triển liên tục và càng học càng mở rộng được tầm nhìn. Bạn hợp với việc học theo nhóm và trao đổi kiến thức, thành tích đến từ sự tích lũy đều đặn qua từng ngày.", "Thổ": "Người mệnh Thổ học chắc chắn, ôn luyện bền bỉ và rất ít khi bỏ cuộc giữa chừng dù tiến độ chậm. Bạn tỏa sáng ở những kỳ thi dài hơi cần sự tích lũy, và thành quả học vấn thường bền vững hơn người.", "Thủy": "Người mệnh Thủy tiếp thu linh hoạt, học qua trải nghiệm và giao tiếp thực tế thường hiệu quả hơn ngồi học thuộc lòng. Bạn có duyên với ngoại ngữ và các lĩnh vực biến động, chỉ cần tránh học lan man quá nhiều thứ cùng lúc."}}, "dreamDict": [{"keywords": ["rắn", "con rắn"], "subject": "Mơ thấy rắn", "meaning": "Giấc mơ về rắn thường gắn với những thay đổi đang âm thầm diễn ra trong cuộc sống của bạn, có thể là một cơ hội mới hoặc một mối quan hệ cần thận trọng. Nếu rắn hiền lành không tấn công, đây là dấu hiệu của sự khôn ngoan và khả năng thích nghi. Ngược lại, rắn đuổi cắn nhắc bạn đề phòng người hai mặt quanh mình.", "numbers": [32, 42, 72]}, {"keywords": ["nước", "nước trong", "nước đục"], "subject": "Mơ thấy nước", "meaning": "Nước trong mơ tượng trưng cho cảm xúc và dòng chảy tài lộc. Nước trong xanh, êm ả báo hiệu tâm trí bình an, công việc thuận lợi. Nước đục hoặc chảy xiết cho thấy bạn đang lo lắng, cần chậm lại để xử lý từng việc một.", "numbers": [16, 61, 80]}, {"keywords": ["cá", "con cá", "đàn cá"], "subject": "Mơ thấy cá", "meaning": "Cá là biểu tượng của sự dư dả và may mắn trong tài lộc theo quan niệm dân gian. Mơ thấy đàn cá bơi lội thường báo tin vui về tiền bạc hoặc cơ hội làm ăn đang đến gần. Cá chết hoặc cá mắc cạn lại nhắc bạn cẩn thận kẻo bỏ lỡ thời cơ.", "numbers": [79, 97, 24]}, {"keywords": ["tiền", "tiền giấy", "nhiều tiền"], "subject": "Mơ thấy tiền", "meaning": "Mơ thấy tiền phản ánh mong muốn về sự ổn định và giá trị bản thân của bạn. Nếu trong mơ bạn vui vẻ khi có tiền, sắp tới có thể có khoản thu bất ngờ. Nếu tiền bay mất hoặc bị lấy đi, hãy chú ý chi tiêu và các cam kết tài chính.", "numbers": [19, 91, 38]}, {"keywords": ["vàng", "thỏi vàng", "vàng bạc"], "subject": "Mơ thấy vàng", "meaning": "Vàng trong mơ tượng trưng cho giá trị, thành quả và sự ghi nhận. Mơ thấy vàng thường báo hiệu giai đoạn thu hoạch sau thời gian nỗ lực, hoặc một cơ hội nâng cao vị thế. Tuy nhiên cũng nhắc bạn đừng vì lợi trước mắt mà đánh mất uy tín lâu dài.", "numbers": [10, 49, 94]}, {"keywords": ["chó", "con chó"], "subject": "Mơ thấy chó", "meaning": "Chó là hình ảnh của lòng trung thành và bạn bè. Mơ thấy chó thân thiện cho thấy bạn có người đáng tin cậy sẵn sàng giúp đỡ lúc khó khăn. Chó sủa dữ hoặc tấn công lại là lời nhắc nên xem lại một mối quan hệ đang có dấu hiệu rạn nứt.", "numbers": [29, 59, 95]}, {"keywords": ["mèo", "con mèo"], "subject": "Mơ thấy mèo", "meaning": "Mèo trong mơ đại diện cho sự nhạy cảm, trực giác và phần mềm mỏng trong tính cách. Mơ thấy mèo ngoan báo hiệu cuộc sống gia đình yên ấm, có tin vui nhỏ. Mèo hoang hoặc mèo cào cắn nhắc bạn cẩn trọng với những lời ngọt ngào không thật lòng.", "numbers": [18, 58, 85]}, {"keywords": ["gà", "con gà", "đàn gà"], "subject": "Mơ thấy gà", "meaning": "Gà gắn với sự chăm chỉ, khởi đầu mới và tin tức gần nhà. Mơ thấy gà gáy sáng thường báo một ngày mới nhiều năng lượng, công việc có tín hiệu tốt. Gà mái ấp trứng gợi ý kế hoạch của bạn đang trong giai đoạn ủ mầm, cần kiên nhẫn thêm.", "numbers": [27, 47, 74]}, {"keywords": ["lợn", "heo", "con lợn"], "subject": "Mơ thấy lợn", "meaning": "Lợn là biểu tượng của sự no đủ và tích lũy. Mơ thấy lợn béo khỏe thường được xem là điềm lành về tài chính, làm ăn có lãi. Lợn gầy ốm hoặc bỏ ăn lại nhắc bạn kiểm tra lại dòng tiền và tránh đầu tư vội vàng.", "numbers": [7, 47, 76]}, {"keywords": ["trâu", "con trâu"], "subject": "Mơ thấy trâu", "meaning": "Trâu tượng trưng cho sức lao động bền bỉ và nền tảng gia đình. Mơ thấy trâu ra đồng gợi ý thành quả sẽ đến từ sự chăm chỉ chứ không phải may rủi. Nếu trâu húc hoặc bỏ chạy, bạn nên chú ý sức khỏe và tránh ôm đồm quá nhiều việc.", "numbers": [13, 31, 86]}, {"keywords": ["ngựa", "con ngựa"], "subject": "Mơ thấy ngựa", "meaning": "Ngựa trong mơ báo hiệu sự tiến lên, di chuyển và khát vọng tự do. Ngựa phi nước đại cho thấy cơ hội thăng tiến hoặc chuyến đi quan trọng đang tới. Ngựa bị thương nhắc bạn đừng nóng vội, hãy giữ sức cho chặng đường dài.", "numbers": [12, 52, 72]}, {"keywords": ["chim", "con chim", "đàn chim"], "subject": "Mơ thấy chim", "meaning": "Chim là sứ giả của tin tức và hy vọng. Mơ thấy chim bay cao, hót vang thường báo tin vui từ xa hoặc một cơ hội mở ra trước mắt. Chim bị nhốt trong lồng cho thấy bạn đang cảm thấy bị bó buộc, cần tìm cách giải phóng bản thân.", "numbers": [23, 56, 87]}, {"keywords": ["bay", "bay lên", "biết bay"], "subject": "Mơ thấy mình bay", "meaning": "Bay trong mơ là cảm giác vượt qua giới hạn và trút bỏ áp lực. Nếu bạn bay nhẹ nhàng, thoải mái, đây là dấu hiệu tinh thần đang thăng hoa, công việc có bước tiến. Bay trong sợ hãi hoặc mất kiểm soát nhắc bạn đang đặt mục tiêu quá cao so với thực lực hiện tại.", "numbers": [3, 30, 83]}, {"keywords": ["rơi", "rơi xuống", "té ngã"], "subject": "Mơ thấy bị rơi", "meaning": "Cảm giác rơi thường xuất hiện khi bạn lo lắng mất kiểm soát trong một việc quan trọng. Giấc mơ nhắc bạn rà soát lại kế hoạch, đừng để mọi thứ phụ thuộc vào một yếu tố duy nhất. Nếu rơi rồi chạm đất an toàn, khó khăn hiện tại sẽ sớm qua.", "numbers": [4, 40, 84]}, {"keywords": ["răng rụng", "rụng răng", "gãy răng"], "subject": "Mơ thấy răng rụng", "meaning": "Răng rụng trong mơ thường liên quan đến sự lo lắng về hình ảnh bản thân hoặc sức khỏe người thân. Dân gian cũng coi đây là điềm nhắc gia đình cần quan tâm nhau nhiều hơn. Nếu rụng răng mà không đau, một giai đoạn cũ sắp khép lại để nhường chỗ cho điều mới.", "numbers": [5, 50, 85]}, {"keywords": ["người chết", "người đã khuất", "ông bà đã mất"], "subject": "Mơ thấy người chết", "meaning": "Mơ thấy người đã khuất thường xuất phát từ nỗi nhớ và tình cảm chưa nguôi của bạn dành cho họ. Theo quan niệm dân gian, đây cũng là điềm nhắc nên chăm lo bàn thờ, mộ phần chu đáo. Nếu người đó mỉm cười nói chuyện, bạn có thể sắp nhận được sự phù trợ về tinh thần.", "numbers": [14, 41, 74]}, {"keywords": ["đám cưới", "cưới", "lễ cưới"], "subject": "Mơ thấy đám cưới", "meaning": "Đám cưới trong mơ tượng trưng cho sự gắn kết và những cam kết mới. Nếu mơ thấy đám cưới của chính mình, bạn đang đứng trước một quyết định quan trọng cần sự chắc chắn. Đám cưới vui vẻ rộn ràng cũng báo tin hỷ trong gia đình hoặc bạn bè thân thiết.", "numbers": [27, 72, 90]}, {"keywords": ["đám ma", "đám tang", "tang lễ"], "subject": "Mơ thấy đám ma", "meaning": "Trái với nỗi sợ thông thường, mơ thấy đám tang thường được hiểu là sự kết thúc của một giai đoạn khó khăn. Giấc mơ cho thấy bạn sẵn sàng buông bỏ chuyện cũ để bắt đầu lại nhẹ nhàng hơn. Nếu trong mơ bạn khóc nhiều, cảm xúc dồn nén lâu ngày cần được giải tỏa.", "numbers": [7, 70, 87]}, {"keywords": ["em bé", "trẻ sơ sinh", "con nít"], "subject": "Mơ thấy em bé", "meaning": "Em bé là biểu tượng của sự khởi đầu trong sáng và những dự định mới ấp ủ. Mơ thấy em bé khỏe mạnh, tươi cười báo hiệu kế hoạch của bạn đang đi đúng hướng. Bé khóc hoặc ốm yếu nhắc bạn dành thêm sự chăm sóc cho một việc còn non trẻ.", "numbers": [1, 10, 99]}, {"keywords": ["lửa cháy", "lửa", "cháy"], "subject": "Mơ thấy lửa cháy", "meaning": "Lửa trong mơ mang hai mặt: nhiệt huyết, tài lộc rực rỡ hoặc sự nóng nảy mất kiểm soát. Lửa cháy sáng ổn định trong bếp là điềm ấm no, gia đạo thuận hòa. Lửa cháy lan dữ dội nhắc bạn kiềm chế cảm xúc và cẩn thận giấy tờ, điện đóm trong nhà.", "numbers": [27, 72, 99]}, {"keywords": ["nhà cháy", "cháy nhà"], "subject": "Mơ thấy nhà cháy", "meaning": "Mơ thấy nhà cháy thường khiến người mơ hoảng sợ, nhưng dân gian lại cho rằng đây là dấu hiệu biến động lớn sắp xảy ra với gia đình. Có thể là chuyện chuyển nhà, sửa sang hoặc thay đổi trong công việc của người thân. Hãy chủ động kiểm tra an toàn cháy nổ để yên tâm hơn.", "numbers": [5, 43, 67]}, {"keywords": ["mưa", "trời mưa", "mưa to"], "subject": "Mơ thấy mưa", "meaning": "Mưa trong mơ tượng trưng cho sự gột rửa và nguồn tài lộc trời ban. Mưa rào nhẹ, mát mẻ báo hiệu tâm trạng được giải tỏa, công việc hanh thông. Mưa dầm dề gây ngập úng lại cho thấy bạn đang chịu áp lực kéo dài cần tìm người chia sẻ.", "numbers": [7, 47, 67]}, {"keywords": ["sấm", "sấm sét", "tiếng sấm"], "subject": "Mơ thấy sấm sét", "meaning": "Sấm sét là điềm của những biến cố bất ngờ và tiếng nói quyền uy. Mơ nghe tiếng sấm xa cho thấy sắp có tin quan trọng liên quan đến công việc hoặc người có vai vế. Sét đánh gần mình nhắc bạn thận trọng trong lời nói, tránh tranh cãi không đáng có.", "numbers": [6, 60, 66]}, {"keywords": ["cây", "cây xanh", "cây cổ thụ"], "subject": "Mơ thấy cây xanh", "meaning": "Cây xanh tượng trưng cho sự phát triển bền vững và sức khỏe của cả gia đình. Cây tươi tốt, đâm chồi nảy lộc báo hiệu vận khí đang lên, con cháu có tin vui. Cây khô héo nhắc bạn chú ý nghỉ ngơi và chăm sóc người lớn tuổi trong nhà.", "numbers": [8, 48, 84]}, {"keywords": ["hoa", "hoa nở", "bông hoa"], "subject": "Mơ thấy hoa nở", "meaning": "Hoa nở trong mơ là hình ảnh của niềm vui, tình cảm và sự được yêu mến. Người độc thân mơ thấy hoa nở rộ có thể sắp gặp nhân duyên tốt. Hoa nhanh tàn nhắc bạn trân trọng những mối quan hệ hiện tại, đừng để lỡ vì vô tâm.", "numbers": [9, 39, 93]}, {"keywords": ["quả", "trái cây", "hoa quả"], "subject": "Mơ thấy quả chín", "meaning": "Quả chín trong mơ báo hiệu mùa thu hoạch, công sức bỏ ra sắp được đền đáp. Hái được quả ngọt là điềm tốt về tiền bạc lẫn tình cảm. Quả còn xanh hoặc chua cho thấy thời điểm chưa chín muồi, bạn cần chờ thêm thay vì ép tiến độ.", "numbers": [19, 29, 92]}, {"keywords": ["núi", "leo núi", "ngọn núi"], "subject": "Mơ thấy núi", "meaning": "Núi tượng trưng cho thử thách lớn và mục tiêu dài hạn trong đời bạn. Leo lên được đỉnh núi là dấu hiệu bạn đủ bản lĩnh vượt qua khó khăn để đạt thành tựu. Dừng giữa chừng nhắc bạn xem lại chiến lược, có thể cần đồng đội thay vì đi một mình.", "numbers": [17, 71, 86]}, {"keywords": ["biển", "biển lớn", "sóng biển"], "subject": "Mơ thấy biển", "meaning": "Biển trong mơ phản ánh thế giới nội tâm rộng lớn và những khát vọng chưa nói thành lời. Biển lặng, nước trong xanh báo hiệu tương lai rộng mở, có cơ hội đi xa làm ăn. Sóng to gió lớn cảnh báo giai đoạn nhiều biến động, cần giữ vững tay lái.", "numbers": [27, 72, 97]}, {"keywords": ["sông", "dòng sông", "qua sông"], "subject": "Mơ thấy sông", "meaning": "Dòng sông là hình ảnh của dòng đời và sự trôi chảy của thời gian. Nước sông trong, chảy êm cho thấy cuộc sống đang đúng nhịp, tài lộc đều đặn. Qua sông vất vả nhắc bạn sắp phải vượt một cửa ải, nhưng bờ bên kia là điều tốt đẹp.", "numbers": [16, 61, 86]}, {"keywords": ["thuyền", "con thuyền", "đi thuyền"], "subject": "Mơ thấy thuyền", "meaning": "Thuyền tượng trưng cho hành trình và khả năng chèo lái cuộc đời của bạn. Thuyền ra khơi thuận gió báo hiệu kế hoạch xuất hành, khai trương có phần may mắn. Thuyền chòng chành nhắc bạn kiểm tra lại đối tác và chuẩn bị phương án dự phòng.", "numbers": [15, 51, 85]}, {"keywords": ["xe", "xe máy", "ô tô", "đi xe"], "subject": "Mơ thấy xe cộ", "meaning": "Xe trong mơ đại diện cho hướng đi và tốc độ tiến về phía trước của bạn. Lái xe êm ái, làm chủ tay lái cho thấy bạn đang kiểm soát tốt công việc. Xe hỏng, mất phanh là lời nhắc nên giảm tốc, rà soát lại những quyết định vội vàng gần đây.", "numbers": [14, 41, 79]}, {"keywords": ["tai nạn", "tai nạn xe", "đâm xe"], "subject": "Mơ thấy tai nạn", "meaning": "Mơ thấy tai nạn thường phản ánh nỗi lo tiềm ẩn hơn là điềm báo thật, cho thấy bạn đang căng thẳng với một kế hoạch có nhiều rủi ro. Giấc mơ nhắc bạn cẩn trọng khi di chuyển và đừng quyết định việc lớn lúc mệt mỏi. Nếu trong mơ mọi người đều an toàn, trở ngại sẽ được hóa giải.", "numbers": [4, 40, 88]}, {"keywords": ["máu", "chảy máu", "thấy máu"], "subject": "Mơ thấy máu", "meaning": "Máu trong mơ gắn với sinh lực, gia đình ruột thịt và cả tài lộc theo cách hiểu dân gian. Thấy máu đỏ tươi đôi khi được xem là điềm có lộc bất ngờ. Tuy nhiên nếu mơ chảy máu nhiều, bạn nên chú ý sức khỏe và đi kiểm tra khi cơ thể có dấu hiệu lạ.", "numbers": [19, 69, 96]}, {"keywords": ["khóc", "khóc lóc", "nước mắt"], "subject": "Mơ thấy mình khóc", "meaning": "Khóc trong mơ là cách tâm trí giải phóng những cảm xúc bị nén chặt ban ngày. Dân gian có câu cười trong mơ, khóc ngoài đời và ngược lại, nên khóc trong mơ thường được xem là sắp có niềm vui bù đắp. Sau giấc mơ này, bạn nên cho phép mình nghỉ ngơi và chia sẻ nhiều hơn.", "numbers": [11, 21, 71]}, {"keywords": ["cười", "cười lớn", "vui cười"], "subject": "Mơ thấy cười", "meaning": "Tiếng cười trong mơ phản ánh nhu cầu được vui vẻ và kết nối của bạn. Cười cùng người thân báo hiệu gia đạo hòa thuận, có dịp sum họp. Cười một mình hoặc cười gượng nhắc bạn đang che giấu nỗi buồn, đừng ngại tìm sự giúp đỡ khi cần.", "numbers": [21, 42, 84]}, {"keywords": ["đánh nhau", "đánh lộn", "xô xát"], "subject": "Mơ thấy đánh nhau", "meaning": "Đánh nhau trong mơ thường là biểu hiện của mâu thuẫn nội tâm hoặc xung đột chưa được giải quyết ngoài đời. Nếu bạn thắng trong mơ, bạn đang dần lấy lại thế chủ động trong một việc khó. Nếu bị thua, hãy tránh đối đầu trực diện và chọn cách thương lượng mềm mỏng.", "numbers": [3, 33, 83]}, {"keywords": ["thi cử", "đi thi", "bài thi"], "subject": "Mơ thấy thi cử", "meaning": "Mơ đi thi dù đã ra trường từ lâu là giấc mơ rất phổ biến khi bạn cảm thấy bị đánh giá, soi xét. Nó cho thấy bạn đang chịu áp lực phải chứng tỏ bản thân trong công việc. Thi đỗ trong mơ là tín hiệu tốt, báo nỗ lực của bạn sắp được ghi nhận.", "numbers": [17, 27, 77]}, {"keywords": ["trúng số", "trúng thưởng", "trúng vé số"], "subject": "Mơ thấy trúng số", "meaning": "Mơ trúng số phản ánh khát vọng đổi đời và mong chờ một bước ngoặt may mắn. Giấc mơ nhắc rằng cơ hội thật sự thường đến từ sự chuẩn bị chứ không chỉ vận may. Dù vậy, đây cũng là điềm tinh thần tốt, cho thấy bạn đang lạc quan về tương lai.", "numbers": [8, 18, 88]}, {"keywords": ["mất đồ", "mất của", "bị trộm"], "subject": "Mơ thấy mất đồ", "meaning": "Mất đồ trong mơ thường liên quan đến cảm giác bất an, sợ đánh mất điều quý giá trong đời thực. Có thể bạn đang lo về một mối quan hệ, vị trí công việc hoặc bí mật nào đó. Tìm lại được đồ trong mơ là tín hiệu mọi chuyện sẽ dần ổn định trở lại.", "numbers": [6, 60, 86]}, {"keywords": ["nhà mới", "chuyển nhà", "mua nhà"], "subject": "Mơ thấy nhà mới", "meaning": "Nhà mới trong mơ là biểu tượng của giai đoạn sống mới và sự nâng cấp về mọi mặt. Mơ dọn vào nhà khang trang báo hiệu vận khí gia đình đang đi lên, có thể có tin vui về chỗ ở thật. Nhà mới còn trống trải nhắc bạn cần thời gian để thích nghi với thay đổi.", "numbers": [25, 52, 89]}, {"keywords": ["cầu", "cây cầu", "qua cầu"], "subject": "Mơ thấy cầu", "meaning": "Cầu trong mơ tượng trưng cho sự nối kết và bước chuyển quan trọng. Qua cầu suôn sẻ là điềm bạn sắp vượt qua trở ngại để đến bờ thành công. Cầu gãy hoặc rung lắc nhắc bạn thận trọng với một cam kết đang dang dở, cần gia cố lại niềm tin.", "numbers": [26, 62, 86]}, {"keywords": ["thang", "leo thang", "bậc thang"], "subject": "Mơ thấy leo thang", "meaning": "Leo thang lên cao trong mơ là hình ảnh quen thuộc của sự thăng tiến từng bước. Mỗi bậc thang vững chắc cho thấy con đường sự nghiệp của bạn đang đúng hướng dù chậm. Xuống thang hoặc trượt chân nhắc bạn đừng chủ quan khi đang ở vị trí thuận lợi.", "numbers": [17, 71, 83]}, {"keywords": ["gương", "soi gương", "gương vỡ"], "subject": "Mơ thấy gương", "meaning": "Gương trong mơ là biểu tượng của sự tự nhìn nhận và hình ảnh bản thân. Soi gương thấy mặt tươi tắn cho thấy bạn đang hài hòa với chính mình. Gương vỡ hoặc mờ đục nhắc bạn cẩn trọng với những mối quan hệ thiếu trung thực quanh mình.", "numbers": [13, 31, 81]}, {"keywords": ["tóc", "cắt tóc", "tóc dài"], "subject": "Mơ thấy tóc", "meaning": "Tóc gắn với sức sống, hình ảnh cá nhân và những mối bận tâm thường ngày. Mơ cắt tóc thường là mong muốn rũ bỏ chuyện cũ, làm mới bản thân. Tóc rối bù, rụng nhiều phản ánh bạn đang mệt mỏi, cần sắp xếp lại ưu tiên và nghỉ ngơi hợp lý.", "numbers": [7, 37, 73]}, {"keywords": ["sâu", "con sâu", "sâu bọ"], "subject": "Mơ thấy sâu", "meaning": "Sâu trong mơ thường tượng trưng cho những phiền toái nhỏ nhưng dai dẳng mà bạn đang né tránh. Giấc mơ nhắc bạn xử lý dứt điểm từng việc vụn vặt trước khi chúng lớn dần. Sâu hóa bướm lại là điềm đẹp, báo sự lột xác và trưởng thành sau khó khăn.", "numbers": [5, 35, 53]}, {"keywords": ["chuột", "con chuột"], "subject": "Mơ thấy chuột", "meaning": "Chuột trong mơ thường gắn với những lo toan vụn vặt và người tiểu nhân quanh bạn. Chuột chạy vào nhà nhắc bạn kiểm tra lại đồ đạc, giấy tờ và cẩn trọng trong chuyện tiền nong. Bắt được chuột là dấu hiệu bạn sắp hóa giải được một rắc rối kéo dài.", "numbers": [2, 20, 55]}, {"keywords": ["voi", "con voi"], "subject": "Mơ thấy voi", "meaning": "Voi là biểu tượng của sức mạnh điềm tĩnh, trí tuệ và sự bảo trợ của bề trên. Mơ thấy voi thường báo bạn có quý nhân hoặc người lớn tuổi sẵn sàng nâng đỡ. Voi hiền lành đi qua làng còn được dân gian xem là điềm lành cho cả gia đình.", "numbers": [13, 43, 93]}, {"keywords": ["hổ", "con hổ", "cọp"], "subject": "Mơ thấy hổ", "meaning": "Hổ trong mơ đại diện cho quyền lực, thử thách lớn và cả nỗi sợ bị lấn át. Đối mặt hổ mà không hoảng loạn cho thấy bạn đủ bản lĩnh xử lý việc khó. Hổ rượt đuổi nhắc bạn đang tránh né một quyết định quan trọng cần đối diện sớm.", "numbers": [6, 60, 78]}, {"keywords": ["rồng", "con rồng"], "subject": "Mơ thấy rồng", "meaning": "Rồng là linh vật đứng đầu trong tứ linh, mơ thấy rồng được xem là điềm đại cát về công danh và vận hội. Rồng bay lên trời báo hiệu cơ hội thăng hoa hiếm có đang mở ra. Tuy vậy, rồng cũng nhắc bạn giữ tâm khiêm nhường để phúc bền lâu.", "numbers": [10, 29, 92]}, {"keywords": ["phượng", "phượng hoàng", "chim phượng"], "subject": "Mơ thấy phượng hoàng", "meaning": "Phượng hoàng tượng trưng cho sự tái sinh, vẻ đẹp và đức hạnh. Mơ thấy phượng hoàng thường báo một giai đoạn mới rực rỡ sau thời gian nhiều trắc trở, đặc biệt tốt cho phụ nữ và chuyện gia đạo. Hình ảnh này cũng gợi nhân duyên xứng đôi vừa lứa.", "numbers": [9, 39, 90]}, {"keywords": ["tiền rơi", "rơi tiền", "mất tiền"], "subject": "Mơ thấy tiền rơi", "meaning": "Mơ thấy tiền rơi thường phản ánh nỗi lo hao hụt hoặc cảm giác công sức chưa được đền đáp xứng đáng. Giấc mơ nhắc bạn rà soát chi tiêu và các khoản cho vay mượn. Nếu trong mơ nhặt lại được tiền, khó khăn tài chính chỉ là tạm thời.", "numbers": [14, 41, 88]}, {"keywords": ["nhặt tiền", "nhặt được tiền"], "subject": "Mơ thấy nhặt được tiền", "meaning": "Nhặt được tiền trong mơ là điềm được nhiều người yêu thích, báo hiệu lộc nhỏ bất ngờ hoặc cơ hội đến từ nơi không ngờ tới. Song giấc mơ cũng nhắc bạn tỉnh táo: của trời cho kèm theo trách nhiệm, đừng vì lợi nhỏ mà đánh mất điều lớn hơn.", "numbers": [19, 38, 83]}, {"keywords": ["cho tiền", "được cho tiền", "biếu tiền"], "subject": "Mơ thấy được cho tiền", "meaning": "Được cho tiền trong mơ cho thấy bạn đang nhận được sự quan tâm, giúp đỡ từ người xung quanh mà đôi khi chưa nhận ra. Đây cũng là điềm báo công việc có người nâng đỡ, việc khó có người chung tay. Hãy biết ơn và đáp lại bằng sự tử tế khi có dịp.", "numbers": [28, 68, 86]}, {"keywords": ["mưa bão", "bão", "giông bão"], "subject": "Mơ thấy mưa bão", "meaning": "Mưa bão trong mơ phản ánh giai đoạn nhiều sóng gió, cảm xúc trong bạn đang cuộn trào. Bão đến rồi tan cho thấy biến cố dù lớn cũng sẽ qua, quan trọng là giữ nhà cửa và các mối quan hệ nền tảng cho vững. Đang lúc này bạn nên tránh các quyết định đầu tư mạo hiểm.", "numbers": [7, 47, 77]}, {"keywords": ["cầu vồng", "cầu vồng sau mưa"], "subject": "Mơ thấy cầu vồng", "meaning": "Cầu vồng là hình ảnh của hy vọng sau cơn mưa, điềm lành được nhiều người yêu thích. Mơ thấy cầu vồng báo hiệu giai đoạn khó khăn sắp khép lại, niềm vui và cơ hội mới đang ở phía trước. Đây cũng là giấc mơ đẹp cho chuyện tình cảm và lời hứa được thực hiện.", "numbers": [7, 17, 77]}, {"keywords": ["mặt trời", "mặt trời mọc", "ánh nắng"], "subject": "Mơ thấy mặt trời", "meaning": "Mặt trời trong mơ tượng trưng cho năng lượng, danh vọng và sự khởi đầu đầy sinh khí. Mặt trời mọc rực rỡ báo hiệu vận trình đang lên, thích hợp bắt đầu dự định mới. Mặt trời bị mây che nhắc bạn kiên nhẫn, thời cơ tốt cần thêm chút thời gian để lộ rõ.", "numbers": [1, 11, 81]}, {"keywords": ["mặt trăng", "trăng", "trăng sáng"], "subject": "Mơ thấy mặt trăng", "meaning": "Mặt trăng gắn với sự dịu dàng, trực giác và chuyện tình cảm. Trăng tròn sáng trong mơ thường báo gia đình đoàn viên, tình cảm viên mãn. Trăng khuyết hoặc bị che khuất gợi ý có điều còn dang dở trong lòng cần được nói ra và tháo gỡ.", "numbers": [2, 22, 82]}, {"keywords": ["sao", "ngôi sao", "sao băng"], "subject": "Mơ thấy sao", "meaning": "Ngôi sao trong mơ là biểu tượng của ước mơ, định hướng và niềm tin vào tương lai. Thấy sao băng là lúc dân gian khuyên nên ước nguyện, vì cơ hội tốt có thể vụt đến bất ngờ. Bầu trời đầy sao cho thấy bạn đang có nhiều lựa chọn, hãy chọn con đường khiến mình bình an nhất.", "numbers": [3, 13, 93]}, {"keywords": ["chùa", "đi chùa", "ngôi chùa"], "subject": "Mơ thấy chùa", "meaning": "Mơ thấy chùa cho thấy tâm bạn đang tìm về sự bình an và hướng thiện sau những xô bồ. Đây là điềm tốt về mặt tinh thần, nhắc bạn sống chậm lại, làm việc phúc đức để tích lũy may mắn lâu dài. Nếu mơ thắp hương lễ Phật, một tâm nguyện chân thành có thể sớm thành.", "numbers": [1, 31, 91]}, {"keywords": ["phật", "tượng phật", "đức phật"], "subject": "Mơ thấy Phật", "meaning": "Mơ thấy Phật là giấc mơ được xem là rất lành, biểu tượng của sự che chở và tỉnh thức. Giấc mơ nhắc bạn giữ tâm trong sáng, tránh xa thị phi thì vận may tự nhiên tìm đến. Người đang gặp khó khăn mơ thấy Phật thường có thêm niềm tin để vượt qua.", "numbers": [1, 51, 95]}, {"keywords": ["ma quỷ", "ma", "bóng ma"], "subject": "Mơ thấy ma quỷ", "meaning": "Mơ thấy ma thường phản ánh nỗi sợ, ám ảnh hoặc chuyện cũ chưa giải quyết trong lòng bạn, không hẳn là điềm xấu. Nếu bạn không sợ hãi trong mơ, bạn đang dần làm chủ được cảm xúc của mình. Giấc mơ lặp lại nhiều lần nhắc bạn nên nghỉ ngơi, giảm căng thẳng và chia sẻ với người tin cậy.", "numbers": [13, 33, 79]}, {"keywords": ["người yêu cũ", "tình cũ"], "subject": "Mơ thấy người yêu cũ", "meaning": "Mơ về người yêu cũ thường không có nghĩa là còn yêu, mà là tâm trí đang gợi lại một bài học hoặc cảm xúc cũ. Có thể hiện tại của bạn có điểm tương đồng khiến ký ức trỗi dậy. Giấc mơ nhắc bạn trân trọng người hiện tại và khép lại quá khứ một cách nhẹ nhàng.", "numbers": [12, 21, 47]}, {"keywords": ["mang thai", "có bầu", "bầu"], "subject": "Mơ thấy mang thai", "meaning": "Mang thai trong mơ thường tượng trưng cho một ý tưởng, dự án hoặc giai đoạn mới đang hình thành trong cuộc sống của bạn. Đây là điềm của sự thai nghén sáng tạo, cần thời gian nuôi dưỡng mới thành quả. Với người đang mong con, giấc mơ đơn giản phản ánh niềm khao khát chân thành.", "numbers": [9, 49, 94]}, {"keywords": ["sinh con", "đẻ con", "sinh em bé"], "subject": "Mơ thấy sinh con", "meaning": "Mơ sinh con là điềm của thành quả ra đời sau bao ngày chờ đợi, có thể là dự án hoàn thành hoặc tin vui trong gia đình. Sinh nở thuận lợi trong mơ báo mọi việc sẽ hanh thông hơn dự tính. Giấc mơ cũng nhắc bạn chuẩn bị tinh thần cho trách nhiệm mới sắp đến.", "numbers": [10, 20, 90]}, {"keywords": ["bệnh", "ốm", "bị bệnh"], "subject": "Mơ thấy bị bệnh", "meaning": "Mơ thấy mình bị bệnh phần lớn là tín hiệu cơ thể và tâm trí đang kêu gọi được nghỉ ngơi. Đây không phải điềm gở mà là lời nhắc chăm sóc sức khỏe, ngủ đủ và bớt ôm việc. Nếu mơ bệnh rồi khỏi, bạn sắp vượt qua một giai đoạn uể oải để lấy lại phong độ.", "numbers": [4, 44, 84]}, {"keywords": ["bệnh viện", "đi bệnh viện", "khám bệnh"], "subject": "Mơ thấy bệnh viện", "meaning": "Bệnh viện trong mơ tượng trưng cho nhu cầu được chữa lành, cả về thể chất lẫn tinh thần. Giấc mơ xuất hiện khi bạn đang cần sự hỗ trợ chuyên nghiệp hoặc một lời khuyên đáng tin. Ra viện khỏe mạnh trong mơ là dấu hiệu tốt, báo vấn đề đang dần được giải quyết.", "numbers": [14, 34, 74]}, {"keywords": ["trường học", "lớp học", "đi học"], "subject": "Mơ thấy trường học", "meaning": "Trường học trong mơ gắn với bài học cuộc đời và cảm giác được thử thách. Người trưởng thành mơ quay lại lớp thường đang đứng trước một kỹ năng mới cần học hoặc một kỳ đánh giá trong công việc. Học vui vẻ trong mơ cho thấy bạn sẵn sàng tiếp thu và tiến bộ.", "numbers": [17, 37, 57]}, {"keywords": ["công việc", "đi làm", "văn phòng"], "subject": "Mơ thấy công việc", "meaning": "Mơ thấy công việc phản ánh trực tiếp mức độ bận tâm của bạn dành cho sự nghiệp lúc này. Công việc suôn sẻ trong mơ cho thấy bạn đang đi đúng nhịp và được đồng nghiệp hỗ trợ. Nếu mơ bị dồn việc, trễ hạn, hãy xem lại cách sắp xếp và đừng ngại đề xuất chia sẻ khối lượng.", "numbers": [18, 28, 68]}, {"keywords": ["sếp", "ông chủ", "cấp trên"], "subject": "Mơ thấy sếp", "meaning": "Mơ thấy sếp thường liên quan đến áp lực về đánh giá, thành tích hoặc một quyết định cần người phê duyệt. Sếp vui vẻ, khen ngợi trong mơ là tín hiệu nỗ lực của bạn đang được chú ý. Sếp quở trách nhắc bạn rà soát kỹ công việc trước khi trình bày, tránh sai sót nhỏ.", "numbers": [19, 29, 79]}, {"keywords": ["bạn cũ", "bạn học cũ", "gặp bạn cũ"], "subject": "Mơ thấy bạn cũ", "meaning": "Gặp lại bạn cũ trong mơ cho thấy bạn đang nhớ về một thời vô tư hoặc một phần tính cách của chính mình ngày trước. Có thể sắp có dịp kết nối lại với người quen cũ mang theo cơ hội mới. Giấc mơ cũng nhắc bạn dành thời gian cho bạn bè hiện tại.", "numbers": [16, 36, 63]}, {"keywords": ["người lạ", "người lạ mặt"], "subject": "Mơ thấy người lạ", "meaning": "Người lạ trong mơ thường là hình ảnh của những khía cạnh chưa biết trong chính bạn hoặc cơ hội chưa từng thử. Người lạ thân thiện báo hiệu mối quan hệ, đối tác mới đáng để tìm hiểu. Người lạ gây khó chịu nhắc bạn giữ khoảng cách an toàn trong các giao dịch mới.", "numbers": [15, 25, 75]}, {"keywords": ["ăn uống", "ăn cơm", "bữa ăn"], "subject": "Mơ thấy ăn uống", "meaning": "Ăn uống trong mơ tượng trưng cho sự hưởng thụ, nhu cầu được nuôi dưỡng cả thân lẫn tâm. Bữa ăn ngon, sum vầy là điềm gia đình hòa thuận, tài lộc đủ đầy. Ăn một mình hoặc ăn không ngon miệng cho thấy bạn đang thiếu sự sẻ chia trong cuộc sống.", "numbers": [28, 48, 84]}, {"keywords": ["nấu ăn", "nấu cơm", "vào bếp"], "subject": "Mơ thấy nấu ăn", "meaning": "Nấu ăn trong mơ là hình ảnh của sự chăm sóc và khả năng vun vén cho gia đình. Nấu được món ngon được mọi người khen báo hiệu bạn sắp mang niềm vui đến cho người thân. Bếp núc lộn xộn nhắc bạn sắp xếp lại việc nhà và công việc cho khoa học hơn.", "numbers": [24, 42, 84]}, {"keywords": ["bắt cá", "bắt được cá"], "subject": "Mơ thấy bắt cá", "meaning": "Bắt cá trong mơ là điềm nắm bắt cơ hội bằng chính sức mình, được dân gian xem là rất may mắn. Bắt được cá lớn báo thành quả đáng kể trong làm ăn hoặc thi cử. Cá trơn tuột khỏi tay nhắc bạn chuẩn bị kỹ hơn, thời cơ tốt cần sự sẵn sàng đi kèm.", "numbers": [29, 79, 97]}, {"keywords": ["câu cá", "đi câu"], "subject": "Mơ thấy câu cá", "meaning": "Câu cá trong mơ tượng trưng cho sự kiên nhẫn chờ thời và thú vui tĩnh tại. Ngồi câu lâu mà cá cắn câu là dấu hiệu kế hoạch dài hơi của bạn sắp có kết quả. Giấc mơ cũng khuyên bạn đừng nóng ruột, việc tốt thường đến với người biết đợi đúng lúc.", "numbers": [39, 73, 87]}, {"keywords": ["trồng cây", "gieo hạt", "trồng trọt"], "subject": "Mơ thấy trồng cây", "meaning": "Trồng cây trong mơ là điềm gieo nhân lành, đầu tư cho tương lai xa. Hạt nảy mầm, cây lớn nhanh báo hiệu những nỗ lực thầm lặng của bạn đang đâm chồi đúng hướng. Giấc mơ hợp với người đang khởi nghiệp, học hành hoặc vun đắp một mối quan hệ nghiêm túc.", "numbers": [8, 38, 83]}, {"keywords": ["gặt lúa", "thu hoạch lúa", "lúa chín"], "subject": "Mơ thấy gặt lúa", "meaning": "Gặt lúa vàng trong mơ là hình ảnh đẹp của mùa màng bội thu và công sức được đền đáp. Đây là điềm tốt cho người làm nông, kinh doanh và cả người đang chờ kết quả thi cử, phỏng vấn. Lúa chín đầy đồng báo tin vui lan ra cả gia đình, dòng họ.", "numbers": [18, 48, 89]}], "omenDict": [{"meaning": "Dân gian tin rằng hắt xì vào buổi sáng sớm là điềm có người đang nhắc đến bạn với tình cảm tốt đẹp. Ngày hôm đó thường có tin vui nhỏ hoặc cuộc gặp gỡ dễ chịu đang chờ. Hãy bắt đầu ngày mới với tâm thế thoải mái và để ý những lời mời bất ngờ.", "subject": "Hắt xì hơi buổi sáng", "type": "tốt"}, {"meaning": "Hắt xì vào khoảng giữa trưa thường được xem là dấu hiệu có việc bất ngờ xen ngang kế hoạch. Không hẳn xấu, nhưng bạn nên dự phòng thời gian cho những thay đổi nhỏ. Uống đủ nước và nghỉ ngơi một chút sẽ giúp buổi chiều trôi chảy hơn.", "subject": "Hắt xì hơi buổi trưa", "type": "trung bình"}, {"meaning": "Hắt xì hơi vào buổi tối được dân gian gắn với việc có người đang nghĩ ngợi, băn khoăn về bạn. Cũng có thể cơ thể đang báo hiệu mệt mỏi sau một ngày dài. Hãy đi ngủ sớm và hạn chế suy nghĩ nặng nề trước khi ngủ.", "subject": "Hắt xì hơi buổi tối", "type": "trung bình"}, {"meaning": "Theo quan niệm dân gian, nam giới nháy mắt trái thường là điềm có tin vui về tiền bạc hoặc được người khác giúp đỡ. Tuy nhiên nếu nháy liên tục nhiều giờ, đó có thể chỉ là do mỏi mắt, thiếu ngủ. Hãy để mắt nghỉ ngơi và quan sát thêm các dấu hiệu khác trong ngày.", "subject": "Nháy mắt trái ở nam", "type": "tốt"}, {"meaning": "Nam giới nháy mắt phải được dân gian xem là lời nhắc cẩn trọng trong lời ăn tiếng nói, tránh tranh cãi. Bạn nên giữ bình tĩnh khi xử lý việc chung và kiểm tra kỹ giấy tờ trước khi ký. Nếu mắt nháy kèm đau nhức, hãy đi khám thay vì chỉ luận điềm.", "subject": "Nháy mắt phải ở nam", "type": "cần chú ý"}, {"meaning": "Dân gian cho rằng nữ giới nháy mắt trái là điềm dễ xúc động, có chuyện khiến bạn phải suy nghĩ nhiều. Hãy bình tĩnh trước những tin tức bất ngờ và đừng vội quyết định khi cảm xúc đang dâng cao. Nháy mắt kéo dài cũng thường do căng thẳng, thiếu ngủ gây ra.", "subject": "Nháy mắt trái ở nữ", "type": "cần chú ý"}, {"meaning": "Nữ giới nháy mắt phải thường được xem là điềm vui, có thể sắp gặp lại người quen lâu ngày hoặc nhận tin tốt lành. Đây cũng là dấu hiệu khích lệ bạn tự tin hơn trong kế hoạch đang theo đuổi. Dù vậy, đừng quên chăm sóc đôi mắt nếu hiện tượng lặp lại nhiều.", "subject": "Nháy mắt phải ở nữ", "type": "tốt"}, {"meaning": "Ù tai bất chợt theo dân gian là điềm có người đang nhắc đến bạn, ù tai trái thường gắn với lời khen, ù tai phải gắn với lời chê trách. Thực tế, ù tai còn do huyết áp, tiếng ồn hoặc mệt mỏi gây nên. Nếu ù tai kéo dài kèm chóng mặt, bạn nên đi kiểm tra sức khỏe sớm.", "subject": "Ù tai", "type": "trung bình"}, {"meaning": "Chim bay vào nhà thường được xem là điềm lành, báo tin vui hoặc khách quý sắp ghé thăm. Chim hót líu lo trong nhà càng thêm phần may mắn cho gia chủ. Bạn nên mở cửa cho chim tự bay ra nhẹ nhàng, đừng bắt giữ hay xua đuổi mạnh tay.", "subject": "Chim bay vào nhà", "type": "tốt"}, {"meaning": "Bướm bay vào nhà theo tín ngưỡng dân gian là hình ảnh của linh hồn người thân về thăm hoặc tin vui đang đến gần. Bướm màu sáng đậu trong nhà được xem là điềm tốt về tình cảm và gia đạo. Hãy để bướm tự nhiên bay đi, tránh bắt hoặc giết bướm trong nhà.", "subject": "Bướm bay vào nhà", "type": "tốt"}, {"meaning": "Chó lạ tự tìm đến nhà thường được coi là điềm có quý nhân hoặc bạn tốt sắp xuất hiện trong cuộc sống của bạn. Dân gian có câu chó đến nhà thì sang, mèo đến nhà thì khó, nên đây là dấu hiệu đáng mừng. Nếu có thể, hãy cho chó ăn uống tử tế, phúc khí sẽ ở lại lâu hơn.", "subject": "Chó lạ vào nhà", "type": "tốt"}, {"meaning": "Mèo lạ vào nhà theo quan niệm xưa là điềm nhắc gia đình cẩn trọng chi tiêu và giữ gìn của cải. Không cần xua đuổi, bạn chỉ nên chú ý hơn đến các khoản hao hụt nhỏ trong nhà. Nhiều gia đình vẫn nuôi mèo lạ ở lại và coi như thêm bạn đồng hành.", "subject": "Mèo lạ vào nhà", "type": "cần chú ý"}, {"meaning": "Vỡ gương được dân gian xem là điềm không may, nhắc bạn thận trọng trong các mối quan hệ và tránh hiểu lầm. Khi gương vỡ, nên thu dọn cẩn thận tránh đứt tay và gói kín trước khi bỏ đi. Quan trọng hơn cả là giữ tâm bình tĩnh, đừng vì một điềm nhỏ mà lo lắng cả ngày.", "subject": "Vỡ gương", "type": "cần chú ý"}, {"meaning": "Làm vỡ bát đĩa trong bữa ăn thường khiến nhiều người giật mình, nhưng dân gian cũng có câu vỡ là vỡ lộc, tai qua nạn khỏi. Đây có thể chỉ là nhắc bạn tập trung hơn khi làm việc nhà. Thu dọn mảnh vỡ kỹ càng và mọi chuyện sẽ yên ổn.", "subject": "Vỡ bát đĩa", "type": "trung bình"}, {"meaning": "Rơi đũa trong bữa ăn được xem là điềm có khách sắp đến hoặc có việc khiến bữa ăn bị gián đoạn. Cũng là lời nhắc nhẹ rằng bạn đang vội vàng, thiếu tập trung. Ăn chậm rãi, gác điện thoại sang một bên sẽ giúp bữa cơm trọn vẹn hơn.", "subject": "Rơi đũa khi ăn", "type": "trung bình"}, {"meaning": "Kiến kéo đàn vào nhà thường được dân gian hiểu là điềm nhà có lộc, sắp có tin về tiền bạc hoặc công việc đều đặn. Kiến cũng tượng trưng cho sự chăm chỉ, đoàn kết của các thành viên. Chỉ cần giữ nhà sạch sẽ, tránh để đồ ngọt hở khiến kiến kéo đến quá nhiều.", "subject": "Kiến bò vào nhà thành đàn", "type": "tốt"}, {"meaning": "Dơi trong tiếng Hán đồng âm với chữ phúc, nên dơi bay vào nhà được nhiều nơi xem là điềm phúc lộc ghé thăm. Đặc biệt dơi làm tổ ở góc nhà yên tĩnh được coi là dấu hiệu gia đạo ổn định. Bạn không nên đốt đuổi dơi, chỉ cần mở lối cho chúng ra vào tự nhiên.", "subject": "Dơi bay vào nhà", "type": "tốt"}, {"meaning": "Tiếng cú kêu gần nhà ban đêm thường bị gắn với điềm không lành trong dân gian, khiến nhiều người bất an. Thực ra cú chỉ đi săn đêm và tiếng kêu là bản năng bình thường của loài này. Thay vì lo lắng, bạn nên kiểm tra cửa nẻo cẩn thận và giữ tinh thần thoải mái trước khi ngủ.", "subject": "Nghe tiếng cú kêu", "type": "cần chú ý"}, {"meaning": "Gà gáy vào giờ lạ, nhất là giữa đêm, được dân gian xem là dấu hiệu có biến động hoặc việc bất thường quanh nhà. Có thể chỉ do gà bị giật mình bởi ánh sáng hay tiếng động lạ. Bạn nên kiểm tra chuồng trại, cửa ngõ một vòng cho yên tâm rồi nghỉ ngơi.", "subject": "Gà gáy vào giờ lạ", "type": "cần chú ý"}, {"meaning": "Mơ thấy rụng răng là giấc mơ phổ biến, dân gian thường gắn với lo lắng về người thân hoặc sự thay đổi lớn trong gia đình. Ở góc độ tâm lý, giấc mơ phản ánh bạn đang stress hoặc sợ mất đi điều quan trọng. Hãy quan tâm sức khỏe bản thân và gọi điện hỏi thăm người nhà thường xuyên hơn.", "subject": "Nằm mơ thấy rụng răng", "type": "cần chú ý"}, {"meaning": "Ngứa bàn tay trái theo dân gian là điềm sắp phải chi tiền hoặc có khoản hao hụt bất ngờ. Bạn nên cân nhắc kỹ trước các quyết định mua sắm trong vài ngày tới. Đây cũng có thể chỉ là da khô hoặc dị ứng nhẹ, đừng quá lo lắng.", "subject": "Ngứa bàn tay trái", "type": "cần chú ý"}, {"meaning": "Ngứa bàn tay phải được nhiều người tin là điềm sắp nhận được tiền hoặc lộc bất ngờ. Có thể là khoản nợ cũ được trả, hoặc cơ hội kiếm thêm đang đến gần. Dù vậy, hãy quản lý tiền khôn ngoan thay vì tiêu xài theo cảm hứng nhất thời.", "subject": "Ngứa bàn tay phải", "type": "tốt"}, {"meaning": "Nóng tai, đỏ tai bất chợt được dân gian giải thích là có người đang nhắc đến bạn, nóng tai trái là lời tốt, nóng tai phải là lời chê. Hiện tượng này cũng thường do thay đổi nhiệt độ hoặc cảm xúc. Hãy uống ngụm nước, thư giãn và đừng suy diễn quá nhiều về người xung quanh.", "subject": "Nóng tai", "type": "trung bình"}, {"meaning": "Đỏ mặt bất chợt không vì lý do rõ ràng đôi khi được xem là điềm có chuyện khiến bạn bối rối hoặc được chú ý nhiều hơn thường lệ. Đây là cơ hội để bạn thể hiện bản thân một cách chân thành. Nếu đỏ mặt kèm nóng bừng kéo dài, hãy chú ý nghỉ ngơi và sức khỏe.", "subject": "Đỏ mặt bất chợt", "type": "trung bình"}, {"meaning": "Chim làm tổ trên mái nhà, ban công là điềm được dân gian rất quý, cho rằng nhà có phúc khí, đất lành chim đậu. Gia đình làm ăn yên ổn, các thành viên hòa thuận là nền tảng của điềm lành này. Bạn nên tránh phá tổ chim, để chúng sinh sống tự nhiên cho nhà thêm sinh khí.", "subject": "Chim làm tổ ở nhà", "type": "tốt"}, {"meaning": "Nhện sa xuống trước mặt thường bị nhiều người sợ, nhưng dân gian lại có câu nhện sa là điềm có tin từ phương xa hoặc khách sắp tới. Nhện cũng tượng trưng cho sự kiên nhẫn và khéo léo trong công việc. Chỉ cần nhẹ nhàng đưa nhện ra chỗ an toàn là được.", "subject": "Nhện sa xuống trước mặt", "type": "trung bình"}, {"meaning": "Thạch sùng kêu trong nhà được xem là hiện tượng bình thường, thậm chí nhiều vùng cho rằng nhà có thạch sùng là nhà sạch, ít côn trùng lạ. Dân gian còn truyền nhau đếm tiếng kêu để đoán việc lành dữ, chủ yếu để vui. Bạn không cần bận tâm, cứ sinh hoạt như thường.", "subject": "Thạch sùng kêu", "type": "trung bình"}, {"meaning": "Cóc vào nhà được dân gian quý trọng vì cóc được xem là linh vật giữ của, cậu ông trời trong truyện cổ. Cóc xuất hiện báo hiệu mùa mưa và cũng là điềm gia đình có lộc về đất đai, tài sản. Đừng xua đuổi hay làm hại cóc, hãy để chúng tự đi khi hết mưa.", "subject": "Cóc vào nhà", "type": "tốt"}, {"meaning": "Ong làm tổ trong nhà hoặc quanh nhà thường được xem là điềm phát đạt, vì ong là biểu tượng của sự chăm chỉ và tích lũy. Tổ ong ở vị trí cao, yên tĩnh được cho là mang theo tài lộc bền vững. Tuy nhiên nếu tổ quá lớn gần lối đi, hãy nhờ người chuyên nghiệp di dời để an toàn.", "subject": "Ong làm tổ trong nhà", "type": "tốt"}, {"meaning": "Chuột chạy ngang nhà hoặc chạy thành đàn được dân gian xem là dấu hiệu nhà có nguồn lương thực dồi dào, nhưng cũng nhắc nhở về hao hụt ngầm. Bạn nên kiểm tra kho chứa, bịt các lỗ hổng và cất giữ đồ ăn cẩn thận. Điềm này chủ yếu nhắc sự chu đáo trong quản lý nhà cửa.", "subject": "Chuột chạy trong nhà", "type": "cần chú ý"}, {"meaning": "Đèn trong nhà tự nhiên chớp tắt, nhấp nháy đôi khi khiến người ta liên tưởng đến điềm lạ, nhưng phần lớn là do bóng đèn sắp hỏng hoặc điện áp không ổn định. Dân gian khuyên lúc này nên giữ tâm an, tránh quyết định việc lớn trong tâm trạng bất an. Hãy kiểm tra hệ thống điện để đảm bảo an toàn cho cả nhà.", "subject": "Đèn tự nhiên chớp tắt", "type": "trung bình"}, {"meaning": "Cây khô tưởng chết bỗng đâm chồi sống lại là điềm được dân gian vô cùng trân trọng, tượng trưng cho hy vọng hồi sinh và vận may quay trở lại. Gia đình có cây như vậy thường tin rằng giai đoạn khó khăn sắp qua. Hãy chăm sóc cây chu đáo như chăm một điềm lành quý giá.", "subject": "Cây khô bỗng sống lại", "type": "tốt"}, {"meaning": "Hoa nở trái mùa, ví dụ nở giữa mùa khô hoặc nở hai lần trong năm, được xem là điềm nhà có tin vui đặc biệt hoặc sự kiện hiếm có sắp xảy ra. Nhiều gia đình coi đây là lộc trời dành cho người chăm cây có tâm. Hãy tận hưởng vẻ đẹp bất ngờ đó và chia sẻ niềm vui với người thân.", "subject": "Hoa nở trái mùa", "type": "tốt"}], "moleFace": [{"meaning": "Nốt ruồi nằm giữa trán thường được xem là dấu hiệu của người có ý chí mạnh, thích tự lập và sớm phải xa nhà lập nghiệp. Nam giới có nốt ruồi này thường quyết đoán nhưng cần kiềm chế tính nóng vội. Nữ giới thì dễ thành công trong sự nghiệp nếu biết mềm mỏng trong các mối quan hệ gia đình.", "position": "Giữa trán"}, {"meaning": "Nốt ruồi ở phía bên trái của trán thường gắn với người có tư duy thực tế, giỏi tính toán chuyện tiền bạc. Người này biết tích lũy từ sớm và ít khi rơi vào cảnh túng thiếu. Tuy vậy, họ cần chú ý đừng quá tính toán trong tình cảm kẻo làm người thân phật lòng.", "position": "Trán bên trái"}, {"meaning": "Nốt ruồi ở trán bên phải thường cho thấy người có số được quý nhân nâng đỡ, đi đâu cũng gặp người tốt giúp sức. Nam giới dễ có cơ hội công danh ở nơi xa. Nữ giới có nốt ruồi này thường khéo giao tiếp và được nhiều người quý mến.", "position": "Trán bên phải"}, {"meaning": "Nốt ruồi ở ấn đường, khoảng giữa hai lông mày, thường thuộc về người có trực giác nhạy bén và khả năng nhìn người khá chuẩn. Họ hợp với công việc cần sự quan sát và phân tích. Điểm cần lưu ý là đừng để sự đa nghi làm ảnh hưởng đến chuyện tình cảm.", "position": "Ấn đường, giữa hai lông mày"}, {"meaning": "Nốt ruồi trên lông mày được dân gian gọi là nốt ruồi giấu ngọc, tượng trưng cho tài năng tiềm ẩn và lộc bất ngờ. Người sở hữu thường thông minh, có khiếu về nghệ thuật hoặc kinh doanh. Nữ giới có nốt ruồi này còn được cho là khéo giữ tiền cho gia đình.", "position": "Trên lông mày"}, {"meaning": "Nốt ruồi ở đuôi lông mày thường cho thấy người sống tình cảm, coi trọng bạn bè và dễ mềm lòng trước người khó khăn. Họ có duyên với các công việc giao tiếp, đối ngoại. Cần chú ý tránh cho vay mượn vì tình cảm mà khó đòi lại.", "position": "Đuôi lông mày"}, {"meaning": "Nốt ruồi ở khóe mắt thường gắn với người đào hoa, có sức hút tự nhiên với người khác giới. Nam giới dễ gặp nhiều mối duyên nhưng cần nghiêm túc mới giữ được hạnh phúc lâu bền. Nữ giới có nốt ruồi này thường tinh tế, biết quan tâm và được bạn đời trân trọng.", "position": "Khóe mắt"}, {"meaning": "Nốt ruồi dưới mắt, vùng thường gọi là lệ đường, theo nhân tướng học liên quan nhiều đến chuyện con cái và cảm xúc. Người có nốt ruồi này thường sống nội tâm, yêu thương con cái hết mực. Họ nên học cách chia sẻ nỗi lòng thay vì giữ kín mọi chuyện một mình.", "position": "Dưới mắt"}, {"meaning": "Nốt ruồi trên mí mắt thường thuộc về người kín đáo, ít phô trương nhưng có nội lực và biết lo xa. Họ giỏi quản lý tài chính cá nhân và thích cuộc sống ổn định. Trong tình cảm, người này chậm mở lòng nhưng khi đã tin ai thì rất chung thủy.", "position": "Trên mí mắt"}, {"meaning": "Nốt ruồi trên sống mũi thường được xem là dấu hiệu liên quan đến đường tài vận và sức khỏe hệ tiêu hóa. Người có nốt ruồi này làm ăn cần cẩn trọng, tránh đầu tư theo cảm tính. Bù lại, họ là người thẳng thắn, có sao nói vậy nên được đồng nghiệp tin cậy.", "position": "Sống mũi"}, {"meaning": "Nốt ruồi ở đầu mũi, chóp mũi, trong dân gian thường gắn với người có lộc ăn uống và khả năng kiếm tiền tốt. Tuy nhiên, tiền đến nhanh cũng dễ đi nhanh nếu không biết giữ. Nam giới cần chú ý chuyện tình cảm ngoài luồng, nữ giới thì nên cẩn thận kẻo bị lợi dụng lòng tốt.", "position": "Đầu mũi"}, {"meaning": "Nốt ruồi ở cánh mũi thường cho thấy người biết vun vén, có duyên với việc buôn bán nhỏ và tích lũy tài sản dần dần. Họ biết nắm bắt cơ hội từ những việc tưởng như nhỏ nhặt. Cần chú ý giữ gìn sức khỏe đường hô hấp và tránh làm việc quá sức.", "position": "Cánh mũi"}, {"meaning": "Nốt ruồi ở gò má bên phải thường thuộc về người có cá tính mạnh, thích nổi bật và có tố chất lãnh đạo. Họ dễ đạt vị trí tốt trong công việc nếu biết lắng nghe cấp dưới. Trong gia đình, người này nên tiết chế cái tôi để giữ hòa khí.", "position": "Gò má phải"}, {"meaning": "Nốt ruồi ở gò má bên trái thường cho thấy người sống thiên về cảm xúc, coi trọng các mối quan hệ thân tình hơn danh vọng. Họ có duyên làm công việc chăm sóc, tư vấn hoặc nghệ thuật. Đôi lúc vì quá cả nể mà họ nhận phần thiệt về mình.", "position": "Gò má trái"}, {"meaning": "Nốt ruồi ngay trên má, phần thịt mềm dưới gò má, thường gắn với người có cuộc sống sung túc về hậu vận, càng về sau càng an nhàn. Thời trẻ họ có thể vất vả đôi chút nhưng biết tích lũy nên tuổi trung niên trở đi khá giả. Đây cũng là nốt ruồi của người biết hưởng thụ cuộc sống.", "position": "Giữa má"}, {"meaning": "Nốt ruồi quanh miệng thường được xem là lộc ăn nói, người có nốt ruồi này thường khéo miệng, dễ thuyết phục người khác. Họ hợp với nghề kinh doanh, giảng dạy, truyền thông. Cần lưu ý ăn nói có chừng mực, tránh vạ miệng trong lúc nóng giận.", "position": "Quanh miệng"}, {"meaning": "Nốt ruồi ở khóe miệng thường là dấu hiệu của người có duyên ăn uống, đi đâu cũng được mời mọc, quý mến. Họ sống lạc quan và biết cách làm người khác vui vẻ. Nữ giới có nốt ruồi này thường được cho là có số hưởng phúc từ nhà chồng.", "position": "Khóe miệng"}, {"meaning": "Nốt ruồi ở môi trên thường thuộc về người giàu cảm xúc, coi trọng tình cảm gia đình và thích chăm sóc người khác qua những bữa ăn ngon. Họ có duyên với nghề ẩm thực hoặc kinh doanh đồ ăn. Trong chuyện tình cảm, họ yêu chân thành và hết mình.", "position": "Môi trên"}, {"meaning": "Nốt ruồi ở môi dưới thường cho thấy người có khẩu vị tinh tế, biết tận hưởng cuộc sống và có lộc về ăn uống, du lịch. Họ làm việc gì cũng cần sự thoải mái mới phát huy được hết khả năng. Cần chú ý đừng để sở thích ăn uống ảnh hưởng đến sức khỏe về lâu dài.", "position": "Môi dưới"}, {"meaning": "Nốt ruồi ở cằm thường gắn với điền trạch, tức là tài sản đất đai và chỗ ở ổn định về sau. Người có nốt ruồi này nếu biết tích lũy từ trẻ thì hậu vận có nhà cửa đàng hoàng. Nam giới tính tình điềm đạm, nữ giới thì biết lo cho gia đình, là chỗ dựa vững chắc cho con cái.", "position": "Cằm"}, {"meaning": "Nốt ruồi ở giữa cằm, ngay phần hõm dưới môi, thường thuộc về người có duyên ngầm và đời sống tình cảm phong phú. Họ cần rõ ràng trong các mối quan hệ để tránh hiểu lầm không đáng có. Về sự nghiệp, người này hợp với công việc sáng tạo, nghệ thuật.", "position": "Hõm dưới môi, giữa cằm"}, {"meaning": "Nốt ruồi ở dái tai là một trong những vị trí được dân gian quý nhất, tượng trưng cho phúc khí, trường thọ và tài lộc dồi dào. Người có nốt ruồi này thường được hưởng phúc từ gia đình và có cuộc sống ít sóng gió. Họ cũng là người biết lắng nghe nên được nhiều người tìm đến tâm sự.", "position": "Dái tai"}, {"meaning": "Nốt ruồi ở vành tai thường cho thấy người thông minh từ nhỏ, học hành sáng dạ và có khả năng tiếp thu nhanh. Tuy thời trẻ có phần bướng bỉnh, càng trưởng thành họ càng điềm đạm. Nữ giới có nốt ruồi vành tai thường khéo tay và có tài quản lý việc nhà.", "position": "Vành tai"}, {"meaning": "Nốt ruồi ở thái dương thường gắn với số được đi xa, có cơ hội làm việc hoặc học tập ở nơi khác quê nhà. Người này năng động, thích khám phá và dễ thích nghi với môi trường mới. Cần chú ý an toàn khi di chuyển và đừng quá mạo hiểm trong các chuyến đi xa.", "position": "Thái dương"}], "moleBody": [{"meaning": "Nốt ruồi ở cổ phía trước thường thuộc về người có duyên ăn nói, dễ tạo thiện cảm trong lần gặp đầu tiên. Tuy nhiên, dân gian cũng nhắc người này cẩn thận trong chi tiêu, tránh vung tay quá trán. Trong tình cảm, họ là người cởi mở và thích sự lãng mạn.", "position": "Cổ phía trước"}, {"meaning": "Nốt ruồi sau gáy thường gắn với người có chỗ dựa vững chắc, được gia đình hoặc quý nhân âm thầm nâng đỡ. Họ sống kín đáo, không thích phô trương thành tích. Đây cũng là nốt ruồi của người biết giữ chữ tín, nói được làm được.", "position": "Sau gáy"}, {"meaning": "Nốt ruồi trên vai phải thường cho thấy người gánh vác nhiều trách nhiệm trong gia đình và công việc. Họ là trụ cột đáng tin cậy nhưng dễ ôm đồm khiến bản thân mệt mỏi. Học cách san sẻ việc với người khác sẽ giúp cuộc sống của họ nhẹ nhàng hơn nhiều.", "position": "Vai phải"}, {"meaning": "Nốt ruồi trên vai trái thường thuộc về người chăm chỉ, chịu thương chịu khó từ khi còn trẻ. Thành quả của họ thường đến chậm nhưng bền vững. Trong hôn nhân, người này biết nhường nhịn nên gia đạo thường yên ấm.", "position": "Vai trái"}, {"meaning": "Nốt ruồi giữa ngực thường được xem là dấu hiệu của người sống giàu tình cảm, yêu ghét rõ ràng và có tham vọng riêng. Nam giới có nốt ruồi này thường quyết liệt trong sự nghiệp. Nữ giới thì mạnh mẽ, độc lập, không thích dựa dẫm vào ai.", "position": "Giữa ngực"}, {"meaning": "Nốt ruồi trên cánh tay thường gắn với người khéo léo, tháo vát, làm nghề gì cũng nhanh nhẹn và có duyên với việc tay chân, kỹ thuật. Họ kiếm tiền bằng chính sức lao động của mình nên tài sản khá vững. Cần chú ý tránh làm việc quá sức gây đau mỏi vai gáy về sau.", "position": "Cánh tay"}, {"meaning": "Nốt ruồi ở khuỷu tay thường cho thấy người linh hoạt, biết xoay xở trong hoàn cảnh khó khăn. Họ có khả năng đàm phán tốt và thường là người hòa giải trong nhóm. Trong tài chính, người này biết co giãn chi tiêu hợp lý theo từng giai đoạn.", "position": "Khuỷu tay"}, {"meaning": "Nốt ruồi trên mu bàn tay thường thuộc về người biết nắm giữ cơ hội, có duyên với tiền bạc qua các mối quan hệ xã hội. Họ rộng rãi với bạn bè nên đôi lúc hao hụt vì những khoản chi không tên. Giữ thói quen ghi chép chi tiêu sẽ giúp họ tích lũy tốt hơn.", "position": "Mu bàn tay"}, {"meaning": "Nốt ruồi trong lòng bàn tay được dân gian coi là nốt ruồi nắm giữ tài lộc, người sở hữu thường biết quản lý tiền bạc và ít khi lâm vào cảnh trắng tay. Họ kín kẽ trong chuyện tài chính, không khoe khoang của cải. Đây cũng là người có ý chí, đã quyết việc gì thì theo đến cùng.", "position": "Lòng bàn tay"}, {"meaning": "Nốt ruồi ở ngón tay thường cho thấy người tỉ mỉ, có năng khiếu với công việc cần sự khéo léo như thủ công, nấu ăn, sửa chữa. Tùy vị trí ngón mà ý nghĩa thiên về sự nghiệp hay tình duyên, nhưng nhìn chung là người có đôi tay tạo ra của cải. Họ nên chọn nghề phát huy được thế mạnh tay nghề của mình.", "position": "Ngón tay"}, {"meaning": "Nốt ruồi ở lưng thường gắn với người có số được nâng đỡ, công việc hay gặp thuận lợi bất ngờ ở những phút quyết định. Họ sống có trách nhiệm và được cấp trên tin tưởng giao việc lớn. Điểm cần chú ý là chăm sóc cột sống và tránh khuân vác nặng thường xuyên.", "position": "Lưng"}, {"meaning": "Nốt ruồi ở eo thường thuộc về người có duyên ngầm, vóc dáng và phong thái dễ thu hút người khác. Trong công việc, họ linh hoạt và biết thích nghi với nhiều môi trường. Về tài chính, người này kiếm được cũng tiêu được, nên cần kế hoạch tiết kiệm rõ ràng.", "position": "Eo"}, {"meaning": "Nốt ruồi ở bụng thường được xem là dấu hiệu của cuộc sống no đủ, có lộc về ăn uống và tài sản tích lũy dần theo thời gian. Người có nốt ruồi này thường biết lo xa, để dành được của ăn của để. Hậu vận của họ nhìn chung an nhàn, con cái hiếu thuận.", "position": "Bụng"}, {"meaning": "Nốt ruồi quanh rốn theo dân gian là vị trí khá đặc biệt, gắn với người có trực giác tốt và đời sống nội tâm phong phú. Nữ giới có nốt ruồi này thường được cho là có duyên với đường con cái. Họ cần giữ ấm cơ thể và chú ý sức khỏe hệ tiêu hóa.", "position": "Quanh rốn"}, {"meaning": "Nốt ruồi ở mông thường gắn với người có hậu vận tốt, càng về sau cuộc sống càng ổn định và sung túc. Họ có khả năng tích lũy tài sản một cách thầm lặng, ít ai biết. Trong tính cách, đây là người hiền hòa, không thích tranh giành với đời.", "position": "Mông"}, {"meaning": "Nốt ruồi ở đùi thường cho thấy người có nền tảng gia đình hoặc tài sản được thừa hưởng, ít nhất cũng có chỗ dựa lúc khởi đầu. Họ đi đứng vững vàng, làm việc có kế hoạch dài hơi. Cần vận động thường xuyên để giữ đôi chân khỏe và tránh các bệnh về khớp khi lớn tuổi.", "position": "Đùi"}, {"meaning": "Nốt ruồi ở đầu gối thường thuộc về người hay phải di chuyển, công tác xa hoặc thay đổi môi trường sống nhiều lần. Mỗi lần thay đổi là một lần họ trưởng thành và tích lũy thêm kinh nghiệm. Họ nên chú ý an toàn khi đi lại, nhất là trong các chuyến đi đường dài.", "position": "Đầu gối"}, {"meaning": "Nốt ruồi ở bắp chân thường gắn với người năng động, thích dịch chuyển và có duyên với công việc phải đi nhiều như kinh doanh, thị trường, du lịch. Họ kiếm tiền từ sự xông xáo của chính mình. Về sức khỏe, cần chú ý đôi chân và tránh đứng ngồi một tư thế quá lâu.", "position": "Bắp chân"}, {"meaning": "Nốt ruồi ở mu bàn chân thường cho thấy người có số đi nhiều nơi, cơ hội mở mang từ những chuyến đi xa quê. Họ thích tự do và khó gắn bó lâu với một chỗ cố định nếu công việc quá nhàm chán. Chọn nghề có yếu tố di chuyển sẽ hợp với họ hơn.", "position": "Mu bàn chân"}, {"meaning": "Nốt ruồi ở lòng bàn chân là vị trí được nhắc đến nhiều trong nhân tướng học, thường gắn với người có tố chất lãnh đạo, đi đâu cũng dễ trở thành người đứng mũi chịu sào. Nếu chăm chỉ và giữ được chữ tín, họ có thể gây dựng vị thế đáng kể. Đây cũng là nốt ruồi của người có phúc về hậu vận, được nhiều người kính trọng.", "position": "Lòng bàn chân"}, {"meaning": "Nốt ruồi ở gót chân thường thuộc về người bền bỉ, chịu được áp lực và không ngại việc khó. Họ là kiểu người đi chậm mà chắc, thành công đến muộn nhưng vững vàng. Trong gia đình, họ là chỗ dựa âm thầm mà mọi người có thể tin cậy.", "position": "Gót chân"}, {"meaning": "Nốt ruồi ở mắt cá chân thường cho thấy người linh hoạt trong giao tiếp, dễ kết bạn và có mạng lưới quan hệ rộng. Những mối quan hệ này thường mang lại cơ hội việc làm bất ngờ cho họ. Cần chú ý giữ gìn xương khớp cổ chân khi vận động mạnh hoặc chơi thể thao.", "position": "Mắt cá chân"}], "tattooDict": [{"advice": "Nên xăm ở vị trí rộng như lưng, ngực hoặc bắp tay và hợp với người mệnh Thủy, mệnh Mộc hoặc người làm ăn cần uy tín.", "meaning": "Rồng là linh vật đứng đầu tứ linh, tượng trưng cho quyền lực, sức mạnh và sự thăng hoa trong công danh. Hình xăm rồng thể hiện khát vọng vươn lên, ý chí làm chủ cuộc đời của người sở hữu. Trong phong thủy, rồng còn mang ý nghĩa chiêu tài, trấn trạch và xua đuổi tà khí.", "motif": "Rồng"}, {"advice": "Hợp với phụ nữ hoặc người mệnh Hỏa, mệnh Thổ; vị trí đẹp nhất là lưng, vai hoặc sau gáy.", "meaning": "Phượng hoàng tượng trưng cho sự tái sinh, vẻ đẹp cao quý và đức hạnh. Hình xăm phượng thể hiện người từng trải qua biến cố nhưng biết đứng dậy mạnh mẽ hơn xưa. Đây cũng là biểu tượng của nhân duyên xứng đôi và cuộc sống viên mãn.", "motif": "Phượng hoàng"}, {"advice": "Hợp với người mệnh Kim, mệnh Thủy; thường xăm ở bắp tay, vai hoặc lưng để phát huy khí thế.", "meaning": "Hổ là chúa sơn lâm, biểu tượng của sức mạnh, lòng dũng cảm và khả năng bảo vệ bản thân cùng gia đình. Hình xăm hổ xuống núi mang ý chí quyết đoán, sẵn sàng đối mặt thử thách. Người xăm hổ thường muốn khẳng định cá tính mạnh và vị thế của mình.", "motif": "Hổ"}, {"advice": "Hợp với người mệnh Thủy, mệnh Kim và người làm kinh doanh; vị trí lưng, bắp tay hoặc đùi là lựa chọn phổ biến.", "meaning": "Cá chép vượt vũ môn hóa rồng là hình ảnh kinh điển của sự kiên trì và thành công sau nỗ lực bền bỉ. Hình xăm cá chép tượng trưng cho tài lộc, sự thăng tiến trong học hành, thi cử và sự nghiệp. Màu sắc cá chép còn được chọn theo bản mệnh để tăng thêm ý nghĩa.", "motif": "Cá chép"}, {"advice": "Hợp với người mệnh Mộc, mệnh Thủy; vị trí cánh tay, sau lưng hoặc cẳng chân đều hài hòa.", "meaning": "Cá koi của Nhật Bản tượng trưng cho may mắn, thịnh vượng và tính kiên nhẫn vượt nghịch cảnh. Mỗi màu cá koi mang một ý nghĩa riêng, từ tài lộc, tình duyên đến sự nghiệp. Hình xăm cá koi thường được chọn bởi người làm kinh doanh cầu sự hanh thông.", "motif": "Cá koi"}, {"advice": "Hợp với người hướng nội, mệnh Thủy hoặc mệnh Mộc; vị trí cổ tay, mắt cá hoặc sau tai rất được ưa chuộng.", "meaning": "Hoa sen là biểu tượng của sự thanh khiết, gần bùn mà chẳng hôi tanh mùi bùn, gắn liền với triết lý nhà Phật. Hình xăm hoa sen thể hiện tâm hồn hướng thiện, mong muốn sống bình an giữa đời nhiều xô bồ. Đây cũng là hình xăm của sự thức tỉnh và trưởng thành nội tâm.", "motif": "Hoa sen"}, {"advice": "Hợp với nữ giới mệnh Hỏa, mệnh Mộc; vị trí vai, xương quai xanh hoặc lưng là đẹp nhất.", "meaning": "Hoa anh đào tượng trưng cho vẻ đẹp mong manh, tuổi thanh xuân và triết lý trân trọng từng khoảnh khắc. Hình xăm hoa anh đào thường gắn với người sống tình cảm, biết yêu thương và tận hưởng hiện tại. Trong văn hóa Nhật, hoa anh đào còn là lời nhắc về sự vô thường của cuộc đời.", "motif": "Hoa anh đào"}, {"advice": "Hợp với người mệnh Thổ, mệnh Hỏa; nên xăm ở lưng, ngực hoặc bắp tay với kích thước vừa phải.", "meaning": "Kỳ lân là linh vật mang điềm lành, tượng trưng cho sự nhân từ, thịnh vượng và con cháu đầy nhà. Khác với rồng hay hổ thiên về uy lực, kỳ lân đại diện cho sức mạnh đi kèm lòng nhân. Hình xăm kỳ lân được nhiều người chọn với mong muốn gia đạo bình an, làm ăn phát đạt.", "motif": "Kỳ lân"}, {"advice": "Hợp với người làm quản lý hoặc mệnh Kim, mệnh Thủy; vị trí bắp tay và ngực phát huy tốt nhất vẻ uy nghi.", "meaning": "Sư tử là biểu tượng của quyền uy, lòng can đảm và khả năng lãnh đạo bẩm sinh. Hình xăm sư tử thể hiện người có khí chất đứng đầu, dám chịu trách nhiệm và bảo vệ người thân. Đây là lựa chọn phổ biến của những người muốn khẳng định bản lĩnh đàn ông hoặc vị thế trong tập thể.", "motif": "Sư tử"}, {"advice": "Hợp với người mệnh Mộc, mệnh Hỏa yêu tự do; vị trí vai, bắp tay hoặc dọc sống lưng rất hợp.", "meaning": "Đại bàng tượng trưng cho tầm nhìn xa, sự tự do và ý chí không khuất phục. Hình xăm đại bàng sải cánh thể hiện khát vọng chinh phục những đỉnh cao mới trong sự nghiệp và cuộc sống. Đại bàng còn là biểu tượng của sự sáng suốt, nhìn thấu cơ hội trước người khác.", "motif": "Đại bàng"}, {"advice": "Hợp với người mệnh Thủy, mệnh Mộc; thường xăm ở cổ tay, vai hoặc sau tai với kích thước nhỏ.", "meaning": "Bướm là hình ảnh của sự lột xác, biến đổi và vẻ đẹp nữ tính. Hình xăm bướm thường được chọn sau một cột mốc quan trọng, đánh dấu giai đoạn mới của cuộc đời. Bướm cũng tượng trưng cho tâm hồn tự do, yêu đời và không thích bị ràng buộc.", "motif": "Bướm"}, {"advice": "Hợp với người mệnh Thủy, mệnh Kim làm nghề biển hoặc kinh doanh; vị trí cẳng tay, bắp chân rất phù hợp.", "meaning": "Sóng nước cuộn trào theo phong cách Nhật Bản tượng trưng cho sức mạnh của thiên nhiên và khả năng thích nghi trước biến động. Hình xăm sóng thể hiện người biết thuận theo thời thế nhưng không bao giờ bị nhấn chìm. Đây cũng là biểu tượng của sự mưu trí và bền bỉ trong làm ăn.", "motif": "Sóng nước"}, {"advice": "Hợp với mọi mệnh, đặc biệt người cần sự bảo hộ tinh thần; vị trí lưng, ngực hoặc bắp tay.", "meaning": "Chữ Om là âm thanh nguyên thủy trong Ấn Độ giáo và Phật giáo, tượng trưng cho sự khai mở tâm linh và bình an nội tại. Hình xăm chữ Om thể hiện người hướng về đời sống tinh thần, tìm kiếm sự cân bằng giữa vật chất và tâm hồn. Nhiều người chọn hình này như một lá bùa nhắc mình sống tỉnh thức mỗi ngày.", "motif": "Chữ Om"}, {"advice": "Hợp với người làm kinh doanh mệnh Kim, mệnh Thổ; vị trí bắp tay, vai hoặc sau lưng.", "meaning": "Tỳ hưu là linh vật chỉ ăn vàng bạc châu báu và không có hậu môn, nên dân gian tin rằng tỳ hưu giữ của, chiêu tài cực mạnh. Hình xăm tỳ hưu được người buôn bán, làm ăn ưa chuộng với mong muốn tiền vào như nước, của cải không thất thoát. Đây là hình xăm mang tính phong thủy rõ rệt nhất trong các linh vật.", "motif": "Tỳ hưu"}, {"advice": "Hợp với người mệnh Mộc, mệnh Thủy cần cân bằng cảm xúc; vị trí cổ tay, sau gáy hoặc xương quai xanh.", "meaning": "Mặt trăng tượng trưng cho sự dịu dàng, trực giác và những chu kỳ thay đổi không ngừng của cuộc sống. Hình xăm mặt trăng khuyết hoặc trăng tròn thường gắn với nữ giới, thể hiện vẻ đẹp bí ẩn và nội tâm sâu sắc. Kết hợp mặt trăng với sao còn mang ý nghĩa ước mơ và định hướng tương lai.", "motif": "Mặt trăng"}, {"advice": "Hợp với người mệnh Hỏa, mệnh Thổ có cá tính mạnh; vị trí cổ tay hoặc mắt cá chân là lựa chọn tinh tế.", "meaning": "Mặt trời là nguồn năng lượng dương mạnh nhất, tượng trưng cho sức sống, danh vọng và sự khởi đầu rực rỡ. Hình xăm mặt trời thể hiện người lạc quan, tràn đầy năng lượng và luôn hướng về phía trước. Trong phong thủy, mặt trời giúp xua tan u ám, mang lại sinh khí cho người sở hữu.", "motif": "Mặt trời"}, {"advice": "Hợp với người mệnh Kim, mệnh Thủy; vị trí dọc sống lưng, bắp tay hoặc đùi thể hiện rõ đường nét đầu lâu nhất.", "meaning": "Đầu lâu trong nghệ thuật xăm không chỉ mang vẻ gai góc mà còn là lời nhắc về sự vô thường và giá trị của từng ngày đang sống. Hình xăm đầu lâu thể hiện cá tính nổi loạn, không sợ hãi và triết lý sống hết mình. Nhiều người kết hợp đầu lâu với hoa hồng để cân bằng giữa sống và chết, cứng rắn và lãng mạn.", "motif": "Đầu lâu"}, {"advice": "Hợp với người mệnh Thổ, mệnh Kim yêu thích sự ổn định; vị trí cẳng tay, vai hoặc bắp chân.", "meaning": "La bàn tượng trưng cho sự định hướng, không lạc đường giữa những lựa chọn của cuộc đời. Hình xăm la bàn thường được chọn bởi người yêu du lịch, làm nghề biển hoặc đang ở ngã rẽ quan trọng. Đây cũng là biểu tượng của việc giữ vững nguyên tắc dù hoàn cảnh thay đổi thế nào.", "motif": "La bàn"}, {"advice": "Hợp với người mệnh Thủy, người làm nghề biển hoặc kinh doanh xa nhà; vị trí cẳng tay và bắp tay rất hợp.", "meaning": "Mỏ neo là biểu tượng của sự vững chãi, an toàn và lòng chung thủy trong tình cảm lẫn công việc. Hình xăm mỏ neo xuất phát từ thủy thủ xưa, thể hiện mong muốn luôn có một bến đỗ bình yên để trở về. Người xăm mỏ neo thường coi trọng gia đình và sự ổn định lâu dài.", "motif": "Mỏ neo"}, {"advice": "Hợp với người mệnh Mộc, mệnh Hỏa; vị trí sau gáy, cổ tay hoặc dọc xương sườn mang ý nghĩa nhắc nhở bản thân mỗi ngày.", "meaning": "Chữ thư pháp, thường là chữ Tâm, chữ Phúc, chữ Nhẫn hoặc tên người thân, thể hiện triết lý sống mà người xăm muốn ghi nhớ suốt đời. Hình xăm chữ đề cao giá trị tinh thần hơn hình thức, càng đơn giản càng sâu sắc. Đây là lựa chọn của người trưởng thành, biết rõ điều gì quan trọng nhất với mình.", "motif": "Chữ thư pháp"}]};
