  var HO = ['Nguyễn', 'Trần', 'Lê', 'Phạm', 'Hoàng', 'Huỳnh', 'Vũ', 'Phan', 'Trương', 'Đặng', 'Ngô', 'Dương', 'Đỗ', 'Lý', 'Bùi'];
