        coinsBox.innerHTML = '<p>' + [0, 0, 0].map(function () { return Math.random() < 0.5 ? '🟡' : '⚪'; }).join(' ') + '</p>';
        if (spins >= 6) {
          clearInterval(iv);
          settle();
        }
